        <div class="col-md-6">${d.study.bring || ed ? `<h3 class="sec-h">Bring next lesson</h3><p${E("study.bring", "What to bring")}>${esc(d.study.bring)}</p>` : ""}${d.study.stretch || ed ? `<h3 class="sec-h">Stretch</h3><p class="mb-0"${E("study.stretch", "Add a stretch")}>${esc(d.study.stretch)}</p>` : ""}</div>
