        <tbody>${(d.plan||[]).map((r,i)=>`<tr><td class="text-nowrap fw-semibold">${esc(r.time)}</td><td><span${E(`plan.${i}.mins`, "0", 1)}>${esc(r.mins)}</span></td><td><span${E(`plan.${i}.activity`)}>${esc(r.activity)}</span></td><td class="text-nowrap">${r.criteria && r.criteria !== "All" ? critBadge(r.criteria) : `<span class="text-body-secondary small">${esc(r.criteria||"")}</span>`}</td>${ed ? `<td class="text-end">${rmBtn("plan."+i, "row")}</td>` : ""}</tr>`).join("")}</tbody>
