/* ---------- what's been taught, following on, and remembering the form ---------- */
const lessonCache = {};
function unitLessons(unit, level){
  const out = [];
  libItems().forEach(it => { if(it.unit === unit && it.level === level){ try{ const L = it.load(); if(L && L.title) out.push(L); }catch{} } });
  return out;
}
function coverage(unit, level){
  const m = {}, add = (c, id) => (m[c] = m[c] || new Set()).add(id);
  unitLessons(unit, level).forEach(L => { if((L.meta || {}).kind !== "Revision / catch-up") ((L.meta || {}).criteria || []).forEach(c => add(c, L.id || L.title)); });
  Object.values(seqs).forEach(s => { if(s.unit === unit && s.level === level) s.rows.forEach(r => { if(r.lessonId) r.criteria.forEach(c => add(c, r.lessonId)); }); });
  return Object.fromEntries(Object.entries(m).map(([k, v]) => [k, v.size]));
}
function paintCoverage(){
  let L, u; try{ L = curLevel(); u = curUnit(); }catch{ return; } if(!u) return;
  const cov = coverage(u.t, L.l);
  $("#crit").querySelectorAll(".taught").forEach(el => { const n = cov[el.dataset.code] || 0; el.hidden = !n; el.textContent = n ? "\u2713" + (n > 1 ? " " + n : "") : ""; el.title = n ? `Already taught in ${n} saved lesson${n > 1 ? "s" : ""}` : ""; });
  const done = u.c.filter(c => cov[c[0]]).length, note = $("#covNote");
  if(note) note.textContent = done ? `${done} of ${u.c.length} criteria in this unit are already in your saved lessons.` : "";
}
let followPrev = null;
function updateFollow(){
  let L, u; try{ L = curLevel(); u = curUnit(); }catch{ return; }
  followPrev = u ? unitLessons(u.t, L.l)[0] || null : null;
  const row = $("#followRow"); if(!row) return;
  row.hidden = !followPrev; if(followPrev){ const w = weakQs(followPrev).length; $("#followName").textContent = `"${followPrev.title}"` + (w ? `, and recap the ${w === 1 ? "question" : w + " questions"} the class found hardest` : ""); }
}
/* the newest quiz results for a lesson: this group's board tally, any board tally, or the online quiz */
function resultsOf(L){
  if(!L) return null;
  const ok = R => R && Array.isArray(R.pct) && R.pct.some(p => p != null);
  const mine = typeof curGroup === "string" && curGroup && (L.resultsBy || {})[curGroup];
  if(ok(mine)) return mine.pct;
  const c = [L.lastResults, L.quizOnline].filter(ok).sort((a, b) => (b.at || 0) - (a.at || 0));
  return c.length ? c[0].pct : null;
}
function weakQs(L){
  const res = resultsOf(L); if(!res) return [];
  return res.map((p, i) => [p, i]).filter(([p, i]) => p != null && p < 70 && (L.quiz || [])[i]).sort((a, b) => a[0] - b[0]).slice(0, 3)
    .map(([p, i]) => { const q = L.quiz[i]; return {q: q.q, a: (q.options || [])[q.answer] || "", pct: p}; });
}
function lessonSummary(L){
  if(!L) return null;
  const weak = weakQs(L);
  return {title: L.title, objectives: L.objectives || {}, tasks: (L.tasks || []).map(t => t && t.title).filter(Boolean), weak};
}
function prevBlock(f){
  const p = f.prev; if(!p) return "";
  return `
This lesson follows on from the group's last lesson on this unit: "${p.title}".
Last lesson's objectives: All: ${p.objectives.all || ""} | Most: ${p.objectives.most || ""} | Some: ${p.objectives.some || ""}
Last lesson's tasks: ${p.tasks.join("; ") || "not listed"}${Array.isArray(p.weak) && p.weak.length ? `\nIn its exit quiz the class found these hardest:\n${p.weak.map(w => `- ${w.q} (right answer: ${w.a}). Only ${w.pct}% got it right.`).join("\n")}\nOpen the starter with quick retrieval practice on exactly these points, so the gaps are fixed before new learning. Mention in the teacher plan that the starter revisits them.` : typeof p.weak === "string" && p.weak ? `\nIn its exit quiz the class found this hardest: ${p.weak}` : ""}
Pick up from where that lesson finished and do not repeat its activities. Make the starter a quick retrieval of last lesson's key learning that leads into today.`;
}
function seqBlock(f){
  const s = f.seq; if(!s) return "";
  return `
This is week ${s.week}, lesson ${s.n} of ${s.total} in the unit's sequence of learning.
Planned lesson: "${s.title}"${s.focus ? `\nPlanned focus: ${s.focus}` : ""}${s.activity ? `\nPlanned main activity: ${s.activity}` : ""}${s.check ? `\nPlanned check: ${s.check}` : ""}${s.before.length ? `\nEarlier lessons in the sequence (already taught, do not repeat them): ${s.before.join("; ")}` : ""}${s.after ? `\nThe next lesson will be: ${s.after}` : ""}${s.note ? `\nTeacher's note from the last lesson, which this lesson must act on: ${s.note}` : ""}
Keep to the planned focus. Use the planned title unless a clearer one fits.`;
}
async function buildLesson(f, signal){
  const r = await sampleFn.json(buildPrompt(f), {signal, cache: false});
  if(!r || !r.starter || !r.objectives || !Array.isArray(r.plan)) throw {code: "invalid_json"};
  if(f.describe){
    const used = (Array.isArray(r.criteriaUsed) ? r.criteriaUsed : []).map(String).filter(c => f.codes.includes(c));
    if(used.length){ const lines = f.criteria.split("\n"); f = {...f, criteria: lines.filter(l => used.includes(l.split(" ")[0])).join("\n"), codes: f.codes.filter(c => used.includes(c)), aim: ""}; }
  }
  return {id: newId(),
    meta: {course: f.course, level: f.level, unit: f.unit, aim: f.aim, length: f.length, kind: f.kind, criteria: f.codes, critText: f.criteria, notes: f.notes, brief: f.brief,
      seq: f.seq ? {key: f.seq.key, i: f.seq.i, week: f.seq.week} : null, follows: f.prev ? f.prev.title : ""},
    title: r.title || (f.seq && f.seq.title) || "Lesson", starter: {instructions: [], ...r.starter}, objectives: r.objectives,
    steps: r.steps || [], doneBy: r.doneBy || [], plan: r.plan, studentPlan: r.studentPlan || [], howTo: r.howTo || [], tasks: Array.isArray(r.tasks) ? r.tasks : [], teach: cleanTeach(r.teach),
    quiz: cleanQuiz(r.quiz), study: cleanStudy(r.study), stretch: r.stretch || "", support: r.support || "",
    plenary: {instructions: [], ...(r.plenary || {title: "Plenary", prompt: ""})}};
}
function presetForm(course, level, unitTitle){
  $("#course").querySelectorAll("button").forEach(b => b.setAttribute("aria-pressed", b.dataset.v === course));
  if(!levelsFor().length){ $("#course").querySelectorAll("button").forEach((b, i) => b.setAttribute("aria-pressed", i === 0)); fillLevels("Level 3"); return false; }
  fillLevels(level);
  const i = curLevel().u.findIndex(u => u.t === unitTitle); if(i < 0) return false;
  $("#unit").value = i; fillAims(); fillBriefs(); return true;
}
function planNext(d){
  const m = d.meta || {}; if(!presetForm(m.course, m.level, m.unit)) return;
  const s = seqs[[m.course, m.level, m.unit].join("|")];
  if(m.seq || (s && s.rows.some(r => r.lessonId))){ setView("seq"); return; }
  $("#aim").value = "*"; fillCrit();
  const cov = coverage(m.unit, m.level), boxes = [...$("#crit").querySelectorAll("input")], fresh = boxes.filter(b => !cov[b.value]);
  boxes.forEach(b => { b.checked = fresh.length ? fresh.includes(b) : true; }); updateCritCount();
  const st = $("#status"); st.className = "status";
  st.textContent = fresh.length && fresh.length < boxes.length ? "Ticked the criteria you haven't taught yet. Adjust them, then press Build lesson." : "Pick the criteria for the next lesson, then press Build lesson.";
  $("#form").scrollIntoView({behavior: "smooth", block: "start"});
}
function rememberForm(){ try{ localStorage.setItem("lb_form", JSON.stringify({course: getCourse(), level: curLevel().l, unit: curUnit().t, length: $("#length").value, kind: $("#kind").value})); }catch{} }
function restoreForm(){
  let f = null; try{ f = JSON.parse(localStorage.getItem("lb_form") || "null"); }catch{}
  if(f && f.course && presetForm(f.course, f.level, f.unit)){
    if(f.length) $("#length").value = f.length; if(f.kind) $("#kind").value = f.kind;
    if(!$("#length").value) $("#length").selectedIndex = 1; if(!$("#kind").value) $("#kind").selectedIndex = 0;
  } else fillLevels("Level 3");
}
["level", "unit", "length", "kind"].forEach(id => $("#" + id).addEventListener("change", () => { rememberForm(); if(view === "seq" && (id === "level" || id === "unit")){ seqMsgText = ""; renderSeq(); } }));
$("#course").addEventListener("click", e => { if(e.target.closest("button")){ rememberForm(); if(view === "seq"){ seqMsgText = ""; renderSeq(); } } });

