function saveCal(patch){
  cal = patch ? {custom: true, start: calStartIso(), hols: calHols().slice(), keys: {...calKeys()}, themes: {...calThemes()}, ...patch} : {};
  try{ localStorage.setItem("lb_cal", JSON.stringify(cal)); }catch{}
  if(db && myId) db.doc("data/users/" + myId + "/settings/calendar").set({custom: !!cal.custom, start: cal.start || "", hols: cal.hols || [], keys: cal.keys || {}, themes: cal.themes || {}, updatedAt: Date.now()}).catch(() => {});
}

/* ---------- sequence of learning: week-by-week lessons for every unit ---------- */
const KINDS = ["Teaching new content", "Assignment workshop", "Practical", "Revision / catch-up"];
let seqs = {}, seqMsgText = "", seqArm = "", seqBusy = false;
const seqWeeks = {}, seqSteer = {};
try{ seqs = JSON.parse(localStorage.getItem("lb_seqs") || "{}") || {}; }catch{ seqs = {}; }
const seqKeyOf = (course, L, u) => [course, L.l, u.t].join("|");
