    sn.docs.forEach(d => { try{ const s = JSON.parse(d.data().json); if(s && s.key && Array.isArray(s.rows) && (!seqs[s.key] || (seqs[s.key].updatedAt || 0) <= (s.updatedAt || 0))) seqs[s.key] = s; }catch{} });
