    if(!sn.exists) return; const v = sn.data();
    cal = v.custom ? {custom: true, start: v.start, hols: Array.isArray(v.hols) ? v.hols : [], ...(v.keys ? {keys: v.keys} : {}), ...(v.themes ? {themes: v.themes} : {})} : {};
    try{ localStorage.setItem("lb_cal", JSON.stringify(cal)); }catch{}
