  if(row.kind === "Assignment workshop"){
    const cand = BRIEFS.filter(b => b.s === s.course && b.l === s.level && b.u.includes(uk)).map(b => [b, row.briefId === b.id ? 999 : b.c.filter(c => c[0] === uk && set.includes(c[1])).length]).sort((a, b) => b[1] - a[1])[0];
    if(cand && cand[1]) brief = {id: cand[0].id, title: cand[0].a + ": " + cand[0].t, task: row.task || "*"};
  }
  const aims = Object.entries(u.a || {}).filter(([k]) => letters.has(k));
