  if(a === "seq"){ presetForm(it.s.course, it.s.level, it.s.unit); setView("seq"); return; }
  if(a === "build"){ queueJobs([{key: it.s.key, i: it.i, open: true}]); return; }
  if(a === "taught"){ toggleTaught(it.s, it.r); renderWeek(); return; }
  if(a === "pptx" || a === "sheet") return dlLesson(it.r.lessonId, a, say);
  const got = await fetchLesson(it.r.lessonId);
