const solCell = (w, paras, o = {}) => `<w:tc><w:tcPr><w:tcW w:w="${w}" w:type="dxa"/>${o.span ? `<w:gridSpan w:val="${o.span}"/>` : ""}${o.fill ? `<w:shd w:val="clear" w:color="auto" w:fill="${o.fill}"/>` : ""}</w:tcPr>${paras || solP("")}</w:tc>`;
const solRow = cells => `<w:tr><w:trPr><w:cantSplit/></w:trPr>${cells}</w:tr>`;
const ukDate = iso => iso.slice(8, 10) + "/" + iso.slice(5, 7) + "/" + iso.slice(0, 4);
function solAssess(L, row){
  const a = ["Questioning"];
  if(L && (L.quiz || []).length) a.push("Quiz");
  if(row.kind === "Practical" || (L && tasksOf(L).length)) a.push("Observation");
  if(L && L.plenary && L.plenary.prompt) a.push("Written or Verbal Reflection");
  if(L && L.study) a.push("Homework");
  if(row.kind === "Assignment workshop") a.push("Assignment");
  return a;
}
/* one unit: its weeks, with term headings, holiday rows, hand-ins and the built lessons */
async function solUnit(s, say){
  const fu = findUnit(s); if(!fu) return null;
  const pw = s.perWeek || 1, weeks = Math.ceil(s.rows.length / pw), sw = startOf(s), tw = calWeeks(sw - 1 + weeks), allW = calWeeks(sw - 1 + weeks);
  const lessons = []; for(const r of s.rows) lessons.push(await fetchLesson(r.lessonId));
  const dues = unitDues(s.course, fu.L, fu.u);
  const info = Array.from({length: weeks}, (_, w) => { const idx = Array.from({length: pw}, (_, k) => w * pw + k).filter(i => i < s.rows.length); return {date: tw[sw - 1 + w], idx}; });
  // English and maths, and UDL, written once for the unit and kept with the sequence
  const sig = s.rows.map(r => r.lessonId).join(","); let extra = s.sol && s.sol.sig === sig && Array.isArray(s.sol.weeks) && s.sol.weeks.length === weeks ? s.sol.weeks : null;
  if(!extra && sampleFn){
    say(`Writing the English, maths and UDL notes for ${s.unit.replace(/:.*/, "")}...`);
    try{
      const r = await sampleFn.json(`You are a UK Further Education lecturer completing the institution's Sequence of Learning for "${s.unit}" (${s.level} ${s.course}). For each teaching week below write two short entries.
- "em": Contextualise English and maths. How English and maths are practised through this week's topic. Name the actual skill used (for example the writing, speaking, reading, number or data skill). Max 25 words.
- "udl": Universal Design for Learning. The strategies that let every learner access the week (for example choice of format, scaffolds, chunking, visuals, assistive technology). Max 25 words.
UK spelling. Plain language. No em dashes.

Weeks:
${info.map((w, k) => `${k + 1}: ${w.idx.map(i => { const L = lessons[i] || {}; return `${L.title || s.rows[i].title} (tasks: ${tasksOf(L.tasks ? L : {tasks: []}).map(t => t.title).join("; ") || "none listed"}; support: ${String(L.support || "").slice(0, 160)})`; }).join(" | ")}`).join("\n")}

Reply with only this JSON, with exactly ${weeks} items in week order: {"weeks": [{"em": string, "udl": string}]}`, {cache: false});
      const arr = Array.isArray(r) ? r : r && r.weeks;
      if(Array.isArray(arr) && arr.length){ extra = info.map((_, k) => ({em: String((arr[k] || {}).em || ""), udl: String((arr[k] || {}).udl || "")})); if(seqs[s.key]){ s.sol = {sig, weeks: extra}; saveSeq(s); } }
    }catch{}
  }
  if(!extra) extra = info.map(w => ({em: "", udl: w.idx.map(i => (lessons[i] || {}).support || "").filter(Boolean).join(" ")}));
  // which term each teaching week is in: a new term starts after every holiday gap
  const terms = {}; let term = 1; calWeeks(sw - 1 + weeks).forEach((d, i, a) => { if(i && addDays(a[i - 1], 7) !== d) term++; terms[d] = term; });
  let xml = "", lastTerm = 0, prev = "";
  info.forEach((w, k) => {
    const t = terms[w.date] || 1;
    if(prev && addDays(prev, 7) !== w.date) for(let d = addDays(prev, 7); d < w.date; d = addDays(d, 7)) xml += solRow(solCell(SOL_W[0], solP(ukDate(d), {center: true, sp: 120})) + solCell(12844, solP(`End of Term ${lastTerm} Break`, {center: true, b: true, sp: 120}), {span: 6, fill: "E7E6E6"}));
    if(t !== lastTerm){ xml += solRow(solCell(14061, solP("TERM " + t, {b: true, sp: 120}), {span: 7, fill: "FFF2CC"})); lastTerm = t; }
    const rows = w.idx.map(i => s.rows[i]), Ls = w.idx.map(i => lessons[i]);
    const codes = [...new Set(rows.flatMap(r => r.criteria))], due = dues.filter(x => mondayOf(x.due) === w.date), outs = dues.filter(x => mondayOf(x.out) === w.date), rsb = dues.filter(x => mondayOf(x.resub) === w.date);
    const assess = [...new Set(rows.flatMap((r, j) => solAssess(Ls[j], r)))];
    const notes = [...outs.map(x => `${x.b.a} hand out: ${ukDate(x.out)}`), ...due.map(x => `${x.b.a} hand in: ${ukDate(x.due)}`), ...rsb.map(x => `${x.b.a} resubmission: ${ukDate(x.resub)}`)], keyD = calKeys()[w.date] || "", theme = calThemes()[w.date] || ""; if(k === info.length - 1) notes.push("END OF UNIT DELIVERY");
    xml += solRow(
      solCell(SOL_W[0], solP("Week " + (k + 1), {center: true, b: true}) + solP(ukDate(w.date), {center: true})) +
      solCell(SOL_W[1], solP("Criteria:", {b: true}) + solP(codes.join(", ") || "Review of the unit") + solP("Topic(s):", {b: true}) + rows.map(r => solP(r.title)).join("")) +
      solCell(SOL_W[2], w.idx.map((i, j) => { const L = Ls[j] || {}, r = rows[j]; return solP(`Lesson ${i + 1}: ${L.title || r.title}`, {b: true}) + solP((L.objectives && L.objectives.all) || r.focus || "") + (tasksOf(L.tasks ? L : {tasks: []}).length ? solP("Tasks: " + tasksOf(L).map(t => t.title).join("; ")) : "") + solP("Lesson PowerPoint and worksheet: " + fileSlug(L.title ? L : {title: r.title})); }).join("")) +
      solCell(SOL_W[3], assess.map(a => solP("☒ " + a)).join("")) +
      solCell(SOL_W[4], solP(extra[k].em)) + solCell(SOL_W[5], solP(extra[k].udl) + (theme ? solP("Tutorial theme:", {b: true}) + solP(theme) : "")) +
      solCell(SOL_W[6], notes.map(n => solP(n, {b: true})).join("") + (keyD ? keyD.split(/\.\s+/).filter(Boolean).map(t => solP(t.replace(/\.$/, ""))).join("") : "")));
    prev = w.date;
  });
  return SOL_HEAD.replace("<!--ROWS-->", xml);
}
let solBusy = false;
async function dlSol(list, say, year, own){
  if(solBusy) return;
  if(typeof JSZip === "undefined") return say("The Word tools didn't load. Reload the page.", true);
  if(!downloadsApi) return say("Saving files isn't available in this view. Open the page in Crafticulum AI to download.", true);
  solBusy = true;
  try{
    let units = "";
    for(const [n, s] of list.entries()){
      say(`Filling in ${s.unit.replace(/:.*/, "")} (${n + 1} of ${list.length}). Each unit can take up to a minute the first time...`);
      const t = await solUnit(s, say); if(!t) continue;
      units += solP(s.unit, {b: true, sz: 26, sp: 160, brk: n > 0}) + t + solP("");
    }
    say("Building the Word document...");
    const one = list[0], full = one.course === "Esports" && one.level === "Level 2";
    const zip = own ? await JSZip.loadAsync(own) : await JSZip.loadAsync(full ? (await tplGet("SOL_FULL_B64")) : (await tplGet("SOL_TPL_B64")), {base64: true}), f = zip.file("word/document.xml");
    if(!f) throw {code: "no_table"};
    let doc = await f.async("string");
    if(own){
      const i = ["Teaching, Learning and Assessment", "Learning and Assessment", "Student assessment"].map(k => doc.indexOf(k)).find(x => x >= 0);
      const t0 = i == null ? -1 : Math.max(doc.lastIndexOf("<w:tbl>", i), doc.lastIndexOf("<w:tbl ", i)), t1 = i == null ? -1 : doc.indexOf("</w:tbl>", i);
      if(t0 < 0 || t1 < 0) throw {code: "no_table"};
      doc = doc.slice(0, t0) + units.replace(/^<w:p>.*?<\/w:p>/, "") + doc.slice(t1 + 8);
    } else doc = doc.replace("{{TITLE}}", solX(year ? `${one.course} ${one.level}: sequence of learning` : one.unit)).replace("{{COURSE}}", solX(`Course: ${one.level} ${one.course}${curGroup ? " · Group: " + curGroup : ""}`)).replace("<!--UNITS-->", year || full ? units.replace(/<w:pageBreakBefore\/>/, "") : units.replace(/^<w:p>.*?<\/w:p>/, ""));
    zip.file("word/document.xml", doc);
    const blob = await zip.generateAsync({type: "blob", compression: "DEFLATE", mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document"});
    const name = (year ? `${one.course} ${one.level} SOL` : one.unit.replace(/[^A-Za-z0-9]+/g, " ").trim().slice(0, 50) + " SOL") + " 26-27.docx";
    await downloadsApi.save({filename: name, data: blob});
    const again = window.claude ? null : URL.createObjectURL(blob);
    setTimeout(() => { if(again) document.querySelectorAll("#sqMsg,#ypMsg").forEach(el => { if(!el.textContent) return; const k = document.createElement("a"); k.href = again; k.download = name; k.textContent = "Download it again"; k.className = "ms-2 fw-semibold"; el.appendChild(k); }); }, 0);
    say((year ? `Year document saved with ${list.length} unit${list.length === 1 ? "" : "s"}. Units with lessons still to build are left out.` : "Sequence of learning saved on the institution template.") + (full || own ? "" : " This one starts at the weekly table. To keep your course's front pages, use Download, Fill in my own master document."));
  }catch(e){ const no = e && e.code === "declined"; say(no ? "Download cancelled." : e && e.code === "no_table" ? "Couldn't find the Teaching, Learning and Assessment table in that file. Pick the course's sequence of learning Word document." : "Couldn't build the document. Try again.", !no); }
  finally{ solBusy = false; }
}

/* ---------- exit quiz results across a unit ---------- */
let quizOpen = false, quizStats = null;
async function loadQuizStats(s){
  quizStats = {key: s.key, loading: true}; const rows = [], by = {};
  for(const [i, r] of s.rows.entries()){
    if(!r.lessonId) continue; const L = await fetchLesson(r.lessonId), R = L && (curGroup ? (L.resultsBy || {})[curGroup] : L.lastResults), pct = R && Array.isArray(R.pct) ? R.pct.filter(p => p != null) : [];
    if(!pct.length) continue;
    const avg = Math.round(pct.reduce((a, b) => a + b, 0) / pct.length); let w = 0; R.pct.forEach((p, k) => { if(p != null && p < (R.pct[w] ?? 101)) w = k; });
    rows.push({i, title: L.title, avg, hard: (L.quiz || [])[w] ? L.quiz[w].q : ""});
    r.criteria.forEach(c => (by[c] = by[c] || []).push(avg));
  }
  quizStats = {key: s.key, rows, by: Object.entries(by).map(([c, v]) => [c, Math.round(v.reduce((a, b) => a + b, 0) / v.length)]).sort((a, b) => a[1] - b[1])};
  if(view === "seq" && quizOpen) renderSeq();
}
function quizPanel(s){
  if(!quizOpen) return ""; const q = quizStats && quizStats.key === s.key ? quizStats : null;
  if(!q || q.loading) return `<div class="cal-panel small text-body-secondary">Loading quiz results...</div>`;
  if(!q.rows.length) return `<div class="cal-panel small">No exit quiz results for this unit${curGroup ? " for " + esc(curGroup) : ""} yet. Results are kept for the group that's selected when you run the quiz. Run a quiz from the board, count the hands or use the phone quiz, and the results are kept with the lesson.</div>`;
  const tone = p => p >= 70 ? "success" : p >= 50 ? "warning" : "danger";
  return `<div class="cal-panel"><div class="fw-semibold mb-2">Exit quiz results${curGroup ? " · " + esc(curGroup) : ""}</div>
    <div class="d-flex flex-wrap gap-1 mb-3">${q.by.map(([c, p]) => `<span class="badge bg-${tone(p)}-subtle text-${tone(p)}-emphasis border border-${tone(p)}-subtle">${esc(c)} · ${p}%</span>`).join("")}</div>
    <div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Lesson</th><th>Class score</th><th>Hardest question</th></tr></thead><tbody>${q.rows.map(r => `<tr><td>${r.i + 1}. ${esc(r.title)}</td><td class="fw-semibold text-${tone(r.avg)}">${r.avg}%</td><td class="small">${esc(r.hard)}</td></tr>`).join("")}</tbody></table></div>
    <div class="form-text">Criteria are sorted with the weakest first. Results are from the last time each quiz was run.</div></div>`;
}

/* ---------- taught notes, and dragging a unit along the year planner ---------- */
document.addEventListener("focusout", e => {
  const el = e.target.closest && e.target.closest("[data-note]"); if(!el || !el.isConnected || view !== "seq") return;
  const s = ensureSaved(getCourse(), curLevel(), curUnit()), r = s.rows[+el.dataset.note]; if(!r || !r.id) return;
  const v = el.textContent.replace(/\s+/g, " ").trim(), n = {...(gOf(s).notes || {})}; if((n[r.id] || "") === v) return;
  if(v) n[r.id] = v; else delete n[r.id]; gSet(s, "notes", n); saveSeq(s);
});
let ypDrag = null;
$("#out").addEventListener("pointerdown", e => {
  const bar = e.target.closest(".yp-bar"), cell = document.querySelector(".yp-head .yp-c"); if(!bar || !cell || view !== "seq" || batch.running) return;
  ypDrag = {bar, x: e.clientX, w: cell.getBoundingClientRect().width, u: +bar.dataset.u, d: 0};
  try{ bar.setPointerCapture(e.pointerId); }catch{} bar.classList.add("drag"); e.preventDefault();
});
$("#out").addEventListener("pointermove", e => { if(!ypDrag) return; ypDrag.d = Math.round((e.clientX - ypDrag.x) / ypDrag.w); ypDrag.bar.style.transform = `translateX(${ypDrag.d * ypDrag.w}px)`; });
function ypEnd(){
  if(!ypDrag) return; const g = ypDrag; ypDrag = null; g.bar.classList.remove("drag");
  if(g.d){ const L = curLevel(), x = L.u[g.u]; if(x){ const s = ensureSaved(getCourse(), L, x); gSet(s, "startWeek", Math.min(34, Math.max(1, startOf(s) + g.d))); saveSeq(s); Object.keys(seqOpen).forEach(k => delete seqOpen[k]); } }
  if(view === "seq") renderSeq();
}
$("#out").addEventListener("pointerup", ypEnd); $("#out").addEventListener("pointercancel", ypEnd);

/* ---------- cover lesson pack: a script a cover teacher can follow ---------- */
let coverBusy = false;
async function coverPack(){
  if(coverBusy) return;
  const el = $("#deckMsg"), say = (t, bad) => { if(el){ el.className = "idea-msg mt-2" + (bad ? " err" : ""); el.textContent = t; } };
  if(typeof JSZip === "undefined") return say("The Word tools didn't load. Reload the page.", true);
  if(!sampleFn) return say("The cover pack needs this page open inside Crafticulum AI.", true);
  if(!downloadsApi) return say("Saving files isn't available in this view.", true);
  coverBusy = true; say("Writing the cover lesson pack. This can take up to a minute..."); const d = current;
  try{
    const r = await sampleFn.json(`${lessonContext(d)}

The lesson (JSON): ${JSON.stringify({title: d.title, objectives: d.objectives, starter: d.starter, plan: d.plan, tasks: tasksOf(d).map(t => ({title: t.title, mins: t.mins, goal: t.goal, steps: t.steps, check: t.check})), quiz: d.quiz, plenary: d.plenary})}

Write a COVER LESSON PACK so a cover teacher with no subject knowledge can run this exact lesson. Plain English. UK spelling. No em dashes. No criteria codes in what is said to the class.

Reply with only this JSON:
{"summary": string (what the lesson is about and what learners should have done by the end, max 50 words),
 "before": [string] (3 to 5 things to set up or have ready),
 "script": [{"time": string (e.g. "0:00 to 0:05"), "say": string (what to say to the class, word for word, max 60 words), "do": string (what you do and what learners do, max 40 words)}] (one per stage of the plan, in order),
 "answers": [string] (the answers, or what good work looks like, for the starter, each task and each quiz question),
 "ifStuck": [string] (3 to 5 fixes for likely problems, e.g. a learner finishes early, a PC won't log in),
 "finish": string (how to end, what to collect, and what to leave for the usual teacher, max 50 words)}`, {cache: false});
    if(!r || !Array.isArray(r.script) || !r.script.length) throw {code: "invalid_json"};
    const A = v => Array.isArray(v) ? v.map(String).filter(Boolean) : [], H = t => solP(t, {b: true, sz: 26, sp: 140}), li = t => solP("•  " + t, {sz: 22, sp: 50}), m = d.meta || {};
    const W = [1500, 4700, 3400], row = (a, b, c, head) => `<w:tr>${[a, b, c].map((t, i) => solCell(W[i], solP(t, {b: head, sz: 21, sp: 60}), head ? {fill: "E7E6E6"} : {})).join("")}</w:tr>`;
    const body = solP("Cover lesson pack", {sz: 20, sp: 40}) + solP(d.title, {b: true, sz: 36, sp: 80}) + solP(`${m.unit || ""} · ${m.level || ""} · ${m.length || ""}`, {sz: 20, sp: 120}) +
      solP(String(r.summary || ""), {sz: 22, sp: 120}) + H("Before you start") + A(r.before).map(li).join("") + H("Lesson script") +
      `<w:tbl><w:tblPr><w:tblW w:w="9600" w:type="dxa"/><w:tblBorders>${["top", "left", "bottom", "right", "insideH", "insideV"].map(x => `<w:${x} w:val="single" w:sz="4" w:space="0" w:color="BFBFBF"/>`).join("")}</w:tblBorders></w:tblPr><w:tblGrid>${W.map(w => `<w:gridCol w:w="${w}"/>`).join("")}</w:tblGrid>${row("Time", "Say to the class", "What happens", true)}${r.script.map(x => row(String(x.time || ""), String(x.say || ""), String(x.do || ""))).join("")}</w:tbl>` +
      H("Answers and what good work looks like") + A(r.answers).map(li).join("") + H("If something goes wrong") + A(r.ifStuck).map(li).join("") + H("To finish") + solP(String(r.finish || ""), {sz: 22});
    const NS = 'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"', zip = new JSZip(), NOF = {createFolders: false};
    zip.file("[Content_Types].xml", `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>`, NOF);
    zip.file("_rels/.rels", `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`, NOF);
    zip.file("word/document.xml", `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document ${NS}><w:body>${body}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1000" w:right="1134" w:bottom="1000" w:left="1134" w:header="567" w:footer="567" w:gutter="0"/></w:sectPr></w:body></w:document>`, NOF);
    await downloadsApi.save({filename: fileSlug(d) + " cover pack.docx", data: await zip.generateAsync({type: "blob", compression: "DEFLATE", mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document"})});
    say("Cover lesson pack saved.");
  }catch(e){ const c = e && e.code; say(c === "declined" ? "Download cancelled." : c === "invalid_json" ? "The answer came back in the wrong shape. Try again." : ERR[c] || "Couldn't make the cover pack. Try again.", c !== "declined"); }
  finally{ coverBusy = false; }
}

