/* reminders on the board: what goes out or is due this week, and what's due next week */
function boardBanner(d){
  try{
    const m = d && d.meta; if(!m || !m.unit) return "";
    const mon = mondayOf(todayIso()), sun = addDays(mon, 6), nextSun = addDays(mon, 13), items = [];
    asgList(m.course, m.level, m.unit).forEach(x => {
      if(x.out && x.out >= mon && x.out <= sun) items.push(["b", `${x.b.a} ${x.out <= todayIso() ? "has been handed out" : "is handed out " + longDay(x.out)}`]);
      if(x.due && x.due >= todayIso() && x.due <= nextSun) items.push(["p", `${x.b.a} is due ${x.due === todayIso() ? "today" : longDay(x.due)}`]);
      if(x.resub && x.resub >= todayIso() && x.resub <= nextSun) items.push(["y", `${x.b.a} resubmissions are due ${x.resub === todayIso() ? "today" : longDay(x.resub)}`]);
    });
    return items.length ? `<div class="b-alerts">${items.map(([c, t]) => `<span class="b-alert ${c}">${esc(t)}</span>`).join("")}</div>` : "";
  }catch{ return ""; }
}
/* which week of a unit a date lands in */
function unitWeekOf(s, iso, after){
  const m = mondayOf(iso); if(!m) return null;
  const sw = startOf(s), all = calWeeks(sw - 1 + 120); let k = -1;
  if(after){ k = all.findIndex(d => d >= m); } else { all.forEach((d, i) => { if(d <= m) k = i; }); }
  return k < 0 ? null : k - (sw - 1);
}
function workshopIssues(s){
  const fu = findUnit(s); if(!fu) return [];
  const pw = s.perWeek || 1, out = [];
  s.rows.forEach((r, i) => {
    const rb = rowBrief(s, r, fu.u); if(!rb) return;
    const ow = briefOut(rb) ? unitWeekOf(s, briefOut(rb), true) : null, dw = briefDue(rb) ? unitWeekOf(s, briefDue(rb), false) : null, w = Math.floor(i / pw);
    const lo = ow == null ? 0 : ow, hi = dw == null ? Infinity : dw;
    if(ow != null && w < ow) out.push({i, row: r, lo, hi, why: "early"});
    else if(dw != null && w > dw) out.push({i, row: r, lo, hi, why: "late"});
  });
  return out;
}
function fixDates(s){
  const before = s.rows.slice(), pw = s.perWeek || 1, moved = workshopIssues(s).length;
  for(let pass = 0; pass < 5; pass++){
    const iss = workshopIssues(s); if(!iss.length) break;
    const mv = new Set(iss.map(x => x.row)), rest = s.rows.filter(r => !mv.has(r)), want = [], used = new Set();
    // early ones go at the start of their window, late ones as late in it as they fit, so the teaching comes first
    iss.forEach(x => {
      const loP = Math.max(0, x.lo * pw), hiP = Number.isFinite(x.hi) ? Math.max(loP, x.hi * pw + pw - 1) : loP;
      let p = x.why === "early" ? loP : hiP;
      while(used.has(p) && (x.why === "early" ? p < hiP : p > loP)) p += x.why === "early" ? 1 : -1;
      used.add(p); want.push([p, x.row]);
    });
    want.sort((a, b) => a[0] - b[0]).forEach(([p, r]) => rest.splice(Math.min(p, rest.length), 0, r));
    s.rows = rest;
  }
  const left = workshopIssues(s).length; s.edited = true; saveSeq(s);
  if(moved) undoToast(`Moved ${moved} workshop${moved === 1 ? "" : "s"}.`, () => { const q = seqs[s.key]; if(q){ q.rows = before; saveSeq(q); if(view === "seq") renderSeq(); } });
  return left;
}
/* weekly plan: one page per week for every unit you've started */
function weekPlanPage(d, k, first){
  const units = [];
  Object.values(seqs).forEach(s => {
    const fu = findUnit(s); if(!fu || !s.rows.length) return;
    const pw = s.perWeek || 1, of = Math.ceil(s.rows.length / pw), w = k - (startOf(s) - 1); if(w < 0 || w >= of) return;
    const rows = s.rows.slice(w * pw, w * pw + pw).map((r, j) => ({r, i: w * pw + j}));
    const dd = unitDues(s.course, fu.L, fu.u), notes = [];
    dd.forEach(x => { if(mondayOf(x.out) === d) notes.push(`${x.b.a} out ${longDay(x.out)}`); if(mondayOf(x.due) === d) notes.push(`${x.b.a} due ${longDay(x.due)}`); if(mondayOf(x.resub) === d) notes.push(`${x.b.a} resubmission ${longDay(x.resub)}`); });
    units.push({s, w, of, rows, notes});
  });
  units.sort((a, b) => (a.s.course + a.s.level + a.s.unit).localeCompare(b.s.course + b.s.level + b.s.unit, undefined, {numeric: true}));
  return {units, keyD: calKeys()[d] || "", theme: calThemes()[d] || ""};
}
async function dlWeekPlan(weeks, say){
  if(typeof JSZip === "undefined") return say("The Word tools didn't load. Reload the page.", true);
  if(!downloadsApi) return say("Saving files isn't available in this view.", true);
  say("Building the weekly plan...");
  const all = calWeeks(80), W = [2500, 3300, 3700, 1500, 3000], cache = {};
  const get = async id => id ? (cache[id] ||= await fetchLesson(id)) : null;
  const tr = (cells, head) => `<w:tr>${head ? "<w:trPr><w:tblHeader/></w:trPr>" : "<w:trPr><w:cantSplit/></w:trPr>"}${cells.map((t, i) => solCell(W[i], (Array.isArray(t) ? t : [t]).map((x, j) => solP(x, {b: head || (j === 0 && i === 1), sz: 18, sp: 30})).join(""), head ? {fill: "DEEAF6"} : {})).join("")}</w:tr>`;
  let body = "";
  for(const [n, d] of weeks.entries()){
    const k = all.indexOf(d), p = weekPlanPage(d, k);
    body += solP(`Week ${k + 1} · w/c ${fmtDay(d)}`, {b: true, sz: 32, sp: 60, brk: n > 0}) + solP([curGroup ? "Group: " + curGroup : "", p.keyD, p.theme ? "Tutorial theme: " + p.theme : ""].filter(Boolean).join("   ·   ") || " ", {sz: 20, sp: 140});
    if(!p.units.length){ body += solP("Nothing scheduled this week.", {sz: 22}); continue; }
    const rows = [];
    for(const un of p.units) for(const {r, i} of un.rows){
      const L = await get(r.lessonId), ts = L ? tasksOf(L).map(t => t.title) : [];
      rows.push(tr([[un.s.unit, `${un.s.level} ${un.s.course} · week ${un.w + 1} of ${un.of}`], [`Lesson ${i + 1}: ${L ? L.title : r.title}`, L ? "" : "(not built yet)"], [L ? L.objectives.all : r.focus || "", ...(ts.length ? ["Tasks: " + ts.join("; ")] : [])], r.criteria.join(", ") || "Review", un.notes.length ? un.notes : [""]]));
    }
    body += `<w:tbl><w:tblPr><w:tblW w:w="14000" w:type="dxa"/><w:tblBorders>${["top", "left", "bottom", "right", "insideH", "insideV"].map(x => `<w:${x} w:val="single" w:sz="4" w:space="0" w:color="BFBFBF"/>`).join("")}</w:tblBorders></w:tblPr><w:tblGrid>${W.map(w => `<w:gridCol w:w="${w}"/>`).join("")}</w:tblGrid>${tr(["Unit", "Lesson", "What learners will do", "Criteria", "Assignments"], true)}${rows.join("")}</w:tbl>`;
  }
  const zip = new JSZip(), NOF = {createFolders: false};
  zip.file("[Content_Types].xml", `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>`, NOF);
  zip.file("_rels/.rels", `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`, NOF);
  zip.file("word/document.xml", `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${body}<w:sectPr><w:pgSz w:w="16838" w:h="11906" w:orient="landscape"/><w:pgMar w:top="900" w:right="1134" w:bottom="900" w:left="1134" w:header="567" w:footer="567" w:gutter="0"/></w:sectPr></w:body></w:document>`, NOF);
  try{
    const first = all.indexOf(weeks[0]) + 1, last = all.indexOf(weeks[weeks.length - 1]) + 1;
    await downloadsApi.save({filename: `Weekly plan ${weeks.length > 1 ? `weeks ${first} to ${last}` : "week " + first}.docx`, data: await zip.generateAsync({type: "blob", compression: "DEFLATE", mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document"})});
    say(weeks.length > 1 ? `Weekly plan saved, one page for each of the ${weeks.length} weeks.` : "Weekly plan saved.");
  }catch(e){ const no = e && e.code === "declined"; say(no ? "Download cancelled." : "Couldn't build the weekly plan. Try again.", !no); }
}
function halfTermOf(d){ const all = calWeeks(80), i = all.indexOf(d); if(i < 0) return [d]; let a = i, z = i; while(a > 0 && addDays(all[a - 1], 7) === all[a]) a--; while(z < all.length - 1 && addDays(all[z], 7) === all[z + 1]) z++; return all.slice(a, z + 1); }

