/* ---------- downloads for students: the PowerPoint, a task list and the worksheets, kept on your server ---------- */
const FILE_V = 1;
const strHash = s => { let h = 5381; for(let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0; return (h >>> 0).toString(36); };
const fileKeyNew = () => { const a = "abcdefghijkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789", r = new Uint32Array(12); crypto.getRandomValues(r); return [...r].map(x => a[x % a.length]).join(""); };
