  const o = L.objectives || {};
  if(o.all) body += H("By the end of the lesson") + P("All: " + o.all, {sz: 22}) + (o.most ? P("Most: " + o.most, {sz: 22}) : "") + (o.some ? P("Some: " + o.some, {sz: 22}) : "");
  const sp = studentPlan(L); if(sp.length) body += H("Today's plan") + sp.map(r => P(`${r.time}   ${r.what}`, {sz: 22, sp: 40})).join("");
