  const b = e.target.closest("[data-st]"); if(!b) return;
  const a = b.dataset.st, g = b.dataset.g;
  const say = (t, bad) => { seqMsgText = t; const el = $("#sqMsg"); if(el){ el.className = "idea-msg mt-2" + (bad ? " err" : ""); el.textContent = t; } };
  if(a === "grpAdd"){ const inp = $("#stGrpName"), v = (inp.value || "").trim().slice(0, 40); if(!v){ inp.focus(); return; } if(!groupNames.includes(v)) groupNames.push(v); if(!curGroup) curGroup = v; saveGroups(); renderSettings(); say(`Added ${v}.`); setTimeout(() => { const i = $("#stGrpName"); if(i) i.focus(); }, 0); return; }
  if(a === "grpUse"){ curGroup = g || ""; saveGroups(); Object.keys(seqOpen).forEach(k => delete seqOpen[k]); renderSettings(); say(g ? `Now using ${g}.` : "Groups switched off for now."); return; }
  if(a === "grpDel"){ if(stArm !== "del:" + g){ stArm = "del:" + g; renderSettings(); setTimeout(() => { if(stArm === "del:" + g){ stArm = ""; if(view === "settings") renderSettings(); } }, 4000); return; }
    stArm = ""; groupNames = groupNames.filter(x => x !== g); if(curGroup === g) curGroup = ""; saveGroups(); renderSettings(); say(`Removed ${g}.`); return; }
  if(a === "course"){ const v = b.dataset.v; const cb = [...$("#course").querySelectorAll("button")].find(x => x.dataset.v === v); if(cb && getCourse() !== v) cb.click(); renderSettings(); return; }
  if(a === "keys") return showKeys();
  if(a === "setup"){ lsSet("cc_setup_hide", null); renderSettings(); say("The setup list is back on the start page."); return; }
  if(a === "backup") return dlBackup(say);
  if(a === "restore"){ $("#bakFile").click(); return; }
