  return `<section class="setup" aria-labelledby="setupH"><div class="setup-head"><h2 id="setupH">Get set up</h2><span class="setup-n">${done} of ${items.length} done</span><button type="button" class="btn-close" data-setup="hide" aria-label="Hide the setup list"></button></div>
    <div class="setup-bar" role="progressbar" aria-label="Setup progress" aria-valuemin="0" aria-valuemax="${items.length}" aria-valuenow="${done}"><i style="width:${Math.round(done / items.length * 100)}%"></i></div>
    <ol>${items.map(([ok, t, d, go]) => `<li class="${ok ? "done" : ""}"><button type="button" data-setup="${go}"><span class="ck" aria-hidden="true">${ok ? "✓" : ""}</span><span class="min-w-0"><b>${t}</b>${ok ? `<span class="visually-hidden"> (done)</span>` : ""}<small>${d}</small></span></button>${go === "groups" && !ok ? `<button type="button" class="btn btn-sm btn-link setup-skip" data-setup="skipGroups">Not needed</button>` : ""}</li>`).join("")}</ol></section>`;
