/* ---------- Planning: a slim bar that follows you down the page, and drag to reorder ---------- */
let miniObs = null;
function stickTop(){
  const tb = document.querySelector(".topbar"), side = document.querySelector(".side");
  const h = tb && getComputedStyle(tb).display !== "none" ? tb.offsetHeight : side && getComputedStyle(side).position === "sticky" ? side.offsetHeight : 0;
  document.documentElement.style.setProperty("--stick-top", h + "px"); return h;
}
function placeMini(){
  const bar = $("#seqMini"), out = $("#out"); if(!bar || !out) return;
  const r = out.getBoundingClientRect(); bar.style.top = (stickTop() + 8) + "px"; bar.style.left = r.left + "px"; bar.style.width = r.width + "px";
}
function seqMini(){
  if(miniObs){ miniObs.disconnect(); miniObs = null; }
  const out = $("#out"), hero = out && out.querySelector(":scope > .hero"); if(view !== "seq" || !hero) return;
  const s = getSeq(getCourse(), curLevel(), curUnit()), n = s.rows.length, b = s.rows.filter(r => r.lessonId).length, mine = batch.running && batch.jobs[0] && batch.jobs[0].key === s.key;
  const bar = document.createElement("div"); bar.id = "seqMini"; bar.className = "seq-mini"; bar.setAttribute("aria-hidden", "true");
  bar.innerHTML = `<div class="min-w-0 flex-grow-1"><div class="sm-u text-truncate">${esc(curUnit().t)}${curGroup ? ` <span class="text-body-secondary fw-normal">· ${esc(curGroup)}</span>` : ""}</div>
    <div class="d-flex align-items-center gap-2"><div class="mini-bar"><i style="width:${n ? Math.round(b / n * 100) : 0}%"></i></div><span class="small text-body-secondary">${b} of ${n} built</span></div></div>
    ${mine ? `<button type="button" class="btn btn-sm btn-outline-danger" data-mini="stop" tabindex="-1">Stop</button>` : batch.running ? "" : n - b ? `<button type="button" class="btn btn-sm btn-primary" data-mini="buildUnit" tabindex="-1">Build the rest (${n - b})</button>` : `<button type="button" class="btn btn-sm btn-outline-secondary" data-mini="redoAll" tabindex="-1">${seqArm === "redoAll" ? "Regenerate every lesson?" : "Regenerate all"}</button>`}
    <button type="button" class="btn btn-sm btn-link px-1" data-mini-top tabindex="-1">Top</button>`;
  out.appendChild(bar); placeMini();
  if("IntersectionObserver" in window){
    miniObs = new IntersectionObserver(([en]) => { const show = !en.isIntersecting && en.boundingClientRect.top < 0; bar.classList.toggle("show", show); if(show) placeMini(); }, {rootMargin: `-${stickTop()}px 0px 0px 0px`});
    miniObs.observe(hero);
  }
}
document.addEventListener("click", e => { const m = e.target.closest("[data-mini]"); if(m){ const real = [...document.querySelectorAll(`#out [data-sq="${m.dataset.mini}"]`)].find(x => !x.closest("#seqMini")); if(real) real.click(); setTimeout(seqMini, 0); return; } if(e.target.closest("[data-mini-top]")) window.scrollTo({top: 0, behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth"}); });
addEventListener("resize", () => { stickTop(); placeMini(); });
