const _saveSeq0 = saveSeq;
saveSeq = function(s){ if(s && s.isRetro) return saveRetro(); return _saveSeq0.apply(this, arguments); };
async function retroPool(unitTitle){
  const course = getCourse(), thisMon = mondayOf(todayIso()), pool = [], seen = new Set();
  const add = (L, unit) => {
    if(!L || !L.id || seen.has(L.id) || !(L.quiz || []).length) return; seen.add(L.id);
    const pct = resultsOf(L) || [];
    L.quiz.forEach((q, i) => { if(!q || !q.q || !Array.isArray(q.options) || q.options.length < 2) return; const p = pct[i]; pool.push({q: {q: q.q, options: q.options.slice(0, 4), answer: Math.min(q.answer || 0, 3), why: q.why || ""}, lid: L.id, unit, w: 1 + (p == null ? 1 : (100 - p) / 25)}); });
  };
  for(const s of Object.values(seqs)){
    if(s.course !== course || (unitTitle && s.unit !== unitTitle)) continue;
    const pw = s.perWeek || 1, sw = startOf(s), tw = calWeeks(sw - 1 + Math.ceil(s.rows.length / pw)), taught = taughtOf(s);
    for(const [i, r] of s.rows.entries()){ if(!r.lessonId) continue; const wd = tw[sw - 1 + Math.floor(i / pw)] || ""; if(!((r.id && taught.has(r.id)) || (wd && wd < thisMon))) continue; add(await fetchLesson(r.lessonId), s.unit); }
  }
  const inSeq = new Set(); Object.values(seqs).forEach(s => s.rows.forEach(r => r.lessonId && inSeq.add(r.lessonId)));
  libItems().forEach(it => { try{ if(inSeq.has(it.id)) return; if(it.at && it.at > Date.parse(thisMon + "T00:00:00")) return; const L = it.load(); if(!L || (L.meta || {}).course !== course || (unitTitle && L.meta.unit !== unitTitle)) return; add(L, L.meta.unit); }catch{} });
  return pool;
}
function retroPick(pool, n){
  const out = [], per = {}, left = pool.slice(), cap = Math.max(2, Math.ceil(n / Math.max(1, new Set(pool.map(x => x.lid)).size)));
  while(out.length < n && left.length){
    const tot = left.reduce((a, x) => a + x.w, 0); let r = Math.random() * tot, k = 0;
    for(; k < left.length - 1; k++){ r -= left[k].w; if(r <= 0) break; }
    const x = left.splice(k, 1)[0]; if((per[x.lid] || 0) >= cap) continue; per[x.lid] = (per[x.lid] || 0) + 1; out.push(x);
  }
  return out.sort(() => Math.random() - .5);
}
