/* ---------- round 5: lighter loading, automatic backups, tidying away student data ---------- */

/* templates (PowerPoint, Word) load only when a download needs them on the website version */
const TPL_VER = "49d7f1a0c5";
const TPL_FILES = {TPL_B64: "tpl-deck", SOL_TPL_B64: "tpl-sol", SOL_FULL_B64: "tpl-solfull", LP_TPL_B64: "tpl-lp"};
const tplCache = {};
async function tplGet(name){
  if(tplCache[name]) return tplCache[name];
  const v = typeof TPL_VER !== "undefined" ? TPL_VER : "1";
  const r = await fetch(`assets/${TPL_FILES[name]}.txt?v=${v}`, {credentials: "same-origin"});
  if(!r.ok) throw {code: "tpl"};
  return (tplCache[name] = (await r.text()).trim());
}
if(!window.claude && typeof TPL_VER !== "undefined"){
  const warm = () => ["TPL_B64", "LP_TPL_B64"].forEach(n => tplGet(n).catch(() => {}));
  addEventListener("load", () => setTimeout(() => { if(window.requestIdleCallback) requestIdleCallback(warm, {timeout: 4000}); else setTimeout(warm, 4000); }, 6000));
}

