const _editDirty17 = editDirty;
editDirty = function(){ try{ const a = authorNow(), m = current && current.meta; if(a && m && !current.example && (!m.author || m.author.email !== a.email)) m.editedBy = {...a, at: Date.now()}; }catch{} return _editDirty17.apply(this, arguments); };
function bylineHtml(m){ const a = m && m.author, e = m && m.editedBy; if(!(a && a.name) && !(e && e.name)) return "";
  return ` · ${a && a.name ? `By <span class="fw-semibold text-body">${esc(a.name)}</span>` : ""}${e && e.name && (!a || e.email !== a.email) ? `${a && a.name ? ", edited" : "Edited"} by ${esc(e.name)}` : ""}`; }
