/* ===== round 13: your own copy of a lesson, favourites and comments, a fact check, the department page, sign-off,
   the activity log, class pages for students, and deleting a lesson (with the department's password if one is set) ===== */
function acct(){ return (typeof me !== "undefined" && me && !window.claude) ? me : null; }
function prefsNow(){ return (acct() && meInfo && meInfo.prefs) || {}; }
function isMineCopy(d){ return !!(acct() && d && d.meta && d.meta.copyOf && d.meta.author && d.meta.author.email === me.email); }
const OWN_FIELDS = ["lastResults", "resultsBy", "quizOnline", "shareId", "quizShareId", "quizOpen", "quizShowAnswers", "coverId", "liveKey", "fileKey", "filesSig", "quizRoom", "teachCheck"];

