/* swaps the few labels that name Hilltop's own forms */
function plainText(root){
  if(!plainSite() || !root) return;
  const fix = n => { const t = n.nodeValue; if(!t || (t.indexOf("Lesson plan form") < 0 && t.indexOf("Hilltop College") < 0 && t.indexOf("institution's template") < 0)) return;
    const name = (typeof siteNow !== "undefined" && siteNow.name) || "Your institution";
    const nv = t.replace(/On your institution's template, with the quiz QR/g, "Slides for the plan, teaching content, tasks, quiz and plenary").replace(/^(\s*)Lesson plan form/, "$1Lesson plan").replace(/Lesson plan form/g, "lesson plan").replace(/Hilltop College/g, name).replace(/your institution's template/g, "a plain template"); if(nv !== t) n.nodeValue = nv; };
  if(root.nodeType === 3) return fix(root);
  if(root.nodeType !== 1 || /^(SCRIPT|STYLE|TEXTAREA)$/.test(root.tagName)) return;
  const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT); let n; while((n = w.nextNode())) fix(n);
  if(root.querySelectorAll) root.querySelectorAll('[data-lp-open] small').forEach(s => { if(/college's Word form/.test(s.textContent)) s.textContent = "A Word form, filled in from this lesson"; });
}
