/* ---------- plain documents: a simple lesson plan form, slide deck and sequence of learning ---------- */
function miniDocx(body, landscape){
  const zip = new JSZip(), NOF = {createFolders: false};
  zip.file("[Content_Types].xml", `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>`, NOF);
  zip.file("_rels/.rels", `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`, NOF);
  zip.file("word/document.xml", `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${body}<w:sectPr>${landscape ? `<w:pgSz w:w="16838" w:h="11906" w:orient="landscape"/><w:pgMar w:top="720" w:right="720" w:bottom="720" w:left="720" w:header="400" w:footer="400" w:gutter="0"/>` : `<w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1134" w:right="1134" w:bottom="1134" w:left="1134" w:header="567" w:footer="567" w:gutter="0"/>`}</w:sectPr></w:body></w:document>`, NOF);
  return zip.generateAsync({type: "blob", mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document"});
}
const _dlSol20 = dlSol;
dlSol = async function(list, say, year, own){
  if(plainSite() && !own && list && list[0] && typeof JSZip !== "undefined"){
    const one = list[0], P = (t, sz, b) => `<w:p><w:pPr><w:spacing w:after="120"/></w:pPr><w:r><w:rPr>${b ? "<w:b/>" : ""}<w:sz w:val="${sz}"/></w:rPr><w:t xml:space="preserve">${xEsc(t)}</w:t></w:r></w:p>`;
    own = await miniDocx(P(year ? `${one.course} ${one.level}: sequence of learning` : one.unit, 36, true) + P(`${siteNow.name ? siteNow.name + " · " : ""}${one.level} ${one.course}${curGroup ? " · Group: " + curGroup : ""}`, 22) + `<w:tbl><w:tr><w:tc><w:p><w:r><w:t>Teaching, Learning and Assessment</w:t></w:r></w:p></w:tc></w:tr></w:tbl>`, true);
    const say0 = say; say = (t, bad) => say0(String(t).replace("saved on the institution template", "saved").replace(/ This one starts at the weekly table\..*$/, ""), bad);
  }
  return _dlSol20.call(this, list, say, year, own);
};

/* ---------- usage and cost ---------- */
var usage = null, usageMonth = "", usageMsg = "";
function usageLoad(month){ usageMonth = month || ""; authCall("usage", {month: usageMonth}).then(r => { usage = r; if(view === "settings") renderSettings(); }).catch(() => { usage = {error: true}; if(view === "settings") renderSettings(); }); }
const numFmt = n => Number(n || 0).toLocaleString("en-GB");
const tokFmt = n => { n = Number(n || 0); return n >= 1e6 ? (n / 1e6).toFixed(n >= 1e7 ? 0 : 1) + "m" : n >= 1e4 ? Math.round(n / 1e3) + "k" : numFmt(n); };
function usageSection(sec){
  const a = acct(); if(!a || !a.isLead) return "";
  const sup = a.role === "superadmin", sub = sup ? "How much each department and person has asked of Crafticulum AI, what it roughly costs, and a limit for the month." : a.role === "owner" ? "How much each department and person in your institution has asked of Crafticulum AI this month." : "How much your department has asked of Crafticulum AI this month.";
  if(usage === null){ usage = {loading: true}; usageLoad(""); }
  if(usage.loading) return sec("stUsage", "Usage and cost", sub, `<p class="small text-body-secondary mb-0">Loading...</p>`);
  if(usage.error) return sec("stUsage", "Usage and cost", sub, `<p class="small text-body-secondary mb-0">Couldn't load the figures. Reload the page to try again.</p>`);
  const u = usage, s = u.set || {}, t = u.total || {}, priced = t.cost != null, money = v => esc(s.cur || "£") + Number(v || 0).toLocaleString("en-GB", {minimumFractionDigits: 2, maximumFractionDigits: 2});
  const mName = ym => new Date(ym + "-01T00:00:00Z").toLocaleDateString("en-GB", {month: "long", year: "numeric", timeZone: "UTC"});
  const meter = (label, now, cap, fmt) => { const p = Math.min(100, Math.round(now / cap * 100)); return `<div class="use-meter"><div class="d-flex small mb-1"><span class="fw-semibold me-auto">${label}</span><span class="text-body-secondary">${fmt(now)} of ${fmt(cap)}</span></div><div class="progress" role="progressbar" aria-label="${label}" aria-valuenow="${p}" aria-valuemin="0" aria-valuemax="100"><div class="progress-bar${p >= 100 ? " bg-danger" : p >= 80 ? " bg-warning" : ""}" style="width:${p}%"></div></div></div>`; };
  const top = Math.max(1, ...(u.depts || []).map(d => d.calls), ...(u.users || []).map(d => d.calls));
  const rows = (list, withDept) => list.map(r => `<tr><td class="use-n"><div class="fw-semibold text-truncate">${esc(r.name)}</div>${withDept && r.dept && sup ? `<div class="small text-body-secondary text-truncate">${esc(r.dept)}</div>` : ""}</td><td class="use-b"><span style="width:${Math.max(2, Math.round(r.calls / top * 100))}%"></span></td><td class="text-end">${numFmt(r.calls)}</td><td class="text-end text-body-secondary d-none d-sm-table-cell">${tokFmt(r.in + r.out)}</td>${priced ? `<td class="text-end">${money(r.cost)}</td>` : ""}</tr>`).join("");
  const head = first => `<thead><tr><th>${first}</th><th class="use-b" aria-hidden="true"></th><th class="text-end">Requests</th><th class="text-end d-none d-sm-table-cell">Tokens</th>${priced ? `<th class="text-end">Cost</th>` : ""}</tr></thead>`;
  const days = Object.entries(u.days || {}).sort((x, y) => x[0].localeCompare(y[0])), dMax = Math.max(1, ...days.map(d => d[1]));
  const num = (id, label, v, ph, help) => `<div class="col-6 col-md-4"><label class="form-label small fw-semibold mb-1" for="${id}">${label}</label><input class="form-control form-control-sm" id="${id}" inputmode="decimal" value="${v ? esc(String(v)) : ""}" placeholder="${ph}"><div class="form-text">${help}</div></div>`;
  return sec("stUsage", "Usage and cost", sub, `
    ${u.blocked ? `<div class="alert alert-danger small">${esc(u.blocked)}</div>` : ""}
    <div class="d-flex flex-wrap gap-2 align-items-center mb-3"><label class="small fw-semibold" for="useMonth">Month</label><select class="form-select form-select-sm w-auto" id="useMonth">${(u.months || [u.month]).map(m => `<option value="${m}" ${m === u.month ? "selected" : ""}>${mName(m)}</option>`).join("")}</select>${u.model ? `<span class="small text-body-secondary">Model: ${esc(u.model)}</span>` : ""}</div>
    <div class="use-tiles"><div><small>Requests to Crafticulum AI</small><b>${numFmt(t.calls)}</b></div><div><small>Tokens sent</small><b>${tokFmt(t.in)}</b></div><div><small>Tokens written</small><b>${tokFmt(t.out)}</b></div><div><small>Rough cost</small><b>${priced ? money(t.cost) : "–"}</b>${priced ? "" : `<span class="small text-body-secondary">${sup ? "Add the prices below" : "Not set up"}</span>`}</div></div>
    ${u.marker ? `<p class="small text-body-secondary mt-2 mb-0">Of these, Second Marker made ${numFmt(u.marker.calls)} request${u.marker.calls === 1 ? "" : "s"} (${tokFmt(u.marker.in + u.marker.out)} tokens${u.marker.cost != null ? ", about " + money(u.marker.cost) : ""}).</p>` : ""}
    ${s.capCalls && sup ? meter("Requests this month", t.calls, s.capCalls, numFmt) : ""}${s.capCost && priced && sup ? meter("Spend this month", t.cost, s.capCost, money) : ""}
    ${!t.calls ? `<p class="small text-body-secondary mt-3 mb-0">Nothing has been built with Crafticulum AI in ${mName(u.month)} yet.</p>` : `
      ${sup && days.length > 1 ? `<div class="small fw-semibold mt-3 mb-1">Requests each day</div><div class="use-days" role="img" aria-label="Requests each day in ${mName(u.month)}">${days.map(([d, n]) => `<span title="${+d} ${mName(u.month).split(" ")[0]}: ${n} request${n === 1 ? "" : "s"}"><i style="height:${Math.max(4, Math.round(n / dMax * 100))}%"></i><small>${+d}</small></span>`).join("")}</div>` : ""}
      ${sup && (u.depts || []).length ? `<div class="table-responsive mt-3"><table class="table table-sm align-middle use-t mb-0">${head("Department")}<tbody>${rows(u.depts)}</tbody></table></div>` : ""}
      <div class="table-responsive mt-3"><table class="table table-sm align-middle use-t mb-0">${head("Person")}<tbody>${rows(u.users || [], true)}</tbody></table></div>`}
    <div class="form-text mt-2">A request is one thing asked of Crafticulum AI. A full lesson is one request, and reading a specification is several. Tokens are how Crafticulum AI counts text: about four letters each.</div>
    ${sup ? `<details class="conf-g mt-3" ${priced || s.capCalls || s.capCost || s.capDept ? "" : "open"}><summary>Prices and limits</summary>
      <p class="small text-body-secondary mb-2">Type in what Crafticulum AI charges for the model you use and the cost is worked out for you. The prices are on Anthropic's pricing page, per million tokens. Your Anthropic bill is always the real figure.</p>
      <div class="row g-2">${num("usIn", "Price per million tokens sent", s.in, "0.00", "Listed as input")}${num("usOut", "Price per million tokens written", s.out, "0.00", "Listed as output")}<div class="col-6 col-md-4"><label class="form-label small fw-semibold mb-1" for="usCur">Currency sign</label><input class="form-control form-control-sm" id="usCur" maxlength="3" value="${esc(s.cur || "£")}"><div class="form-text">Anthropic prices are in US dollars</div></div>
        ${num("usCapCost", "Most to spend in a month", s.capCost, "No limit", "Needs the prices above")}${num("usCapCalls", "Most requests in a month", s.capCalls, "No limit", "For the whole site")}${num("usCapDept", "Most requests for each department", s.capDept, "No limit", "In a month")}</div>
      <div class="d-flex flex-wrap gap-3 align-items-center mt-3"><button type="button" class="btn btn-sm btn-primary" data-use="save">Save prices and limits</button><span class="idea-msg" role="status">${esc(usageMsg)}</span></div>
      <div class="form-text">When a limit is reached, building with Crafticulum AI stops until the 1st of next month, or until you raise the limit. Everything already built still works.</div></details>` : ""}`);
}
document.addEventListener("change", e => { if(e.target.id === "useMonth") usageLoad(e.target.value); }, true);
document.addEventListener("click", async e => { const b = e.target.closest("[data-use]"); if(!b) return; const v = id => ($("#" + id).value || "").trim();
  b.disabled = true;
  try{ usage = await authCall("usageset", {month: usageMonth, in: v("usIn"), out: v("usOut"), cur: v("usCur"), capCost: v("usCapCost"), capCalls: v("usCapCalls"), capDept: v("usCapDept")}); usageMsg = "Saved."; }
  catch{ usageMsg = "Couldn't save that. Try again."; }
  renderSettings(); const d = [...document.querySelectorAll("#stUsage .conf-g")][0]; if(d) d.open = true; setTimeout(() => { usageMsg = ""; }, 100); });

