/* ===== round 16: Second Marker, which checks learner work against the criteria. A department's leader switches it on and sets how it works.
   Its code is in marker/sm.js, loaded when the page is first opened. Checks go through marker/api.php, so nobody needs their own API key. ===== */
var markerMsg = "", markerStats = null;
function markerNow(){ return (typeof meInfo !== "undefined" && meInfo && meInfo.marker) || {}; }
const MARKER_ICO = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 13l4.5 4.5L18 8"/><path d="M11 17.5l1.5 1.5L21 10.5" opacity=".55"/></svg>`;
/* Second Marker is a page of the app like any other: it's in the menu, is part of the same page and follows the same theme. */
function markerNav(){
  const on = !!(acct() && markerNow().can), nav = document.querySelector(".side .side-nav"); let l = $("#sideMarker");
  if(!on){ if(l) l.remove(); if(view === "marker") setView("home"); return; }
  if(!l && nav){ const after = nav.querySelector('[data-nav="results"]'); (after || nav.lastElementChild).insertAdjacentHTML("afterend", `<button type="button" class="side-link" id="sideMarker" data-nav="marker" aria-label="Second Marker">${MARKER_ICO}<span class="lbl">Second Marker</span></button>`); }
  if(location.hash === "#marker"){ try{ history.replaceState(null, "", location.pathname + location.search); }catch{} setView("marker"); }
}
const themeNow = () => document.documentElement.getAttribute("data-bs-theme") === "dark" ? "dark" : "light";
/* Second Marker's own code is loaded the first time its page is opened, and then stays, so work in progress isn't lost when you look at another page. */
var markerSM = null, markerLoad = null, markerSub = "", markerSel = null;
const MARKER_VER = "dbc5d30e96";
window.ccMarkerCtx = function(){ const m = markerNow(); return {...m, iv: !!(m.iv && me && me.isLead), group: typeof markerGroup === "string" ? markerGroup : "", name: (me && me.name) || "", dept: (me && me.deptName) || "", theme: themeNow()}; };
window.ccMarkerActive = () => view === "marker";
