  const mode = mkGet("btec_check_mode"), cm = mode === "ai" || mode === "manual" ? mode : "ask", model = mkGet("cc_marker_model") || "claude-opus-5-5", batch = mkGet("btec_batch_option") !== "0", pdf = mkGet("btec_pdf_privacy") === "full" ? "full" : "text";
  const log = mkAgree(), all = log.flatMap(e => e.rows || []), same = all.filter(r => r.ai === (r.you === "Y")).length;
  const radio = (name, v, on, t) => `<div class="form-check"><input class="form-check-input" type="radio" name="${name}" id="${name}_${v}" value="${v}" data-mkp="${name}" ${on ? "checked" : ""}><label class="form-check-label small" for="${name}_${v}">${t}</label></div>`;
  const lm = mkGet("btec_learner_mode") === "anon" ? "anon" : "named";
