  const o = bk.off || {}, c = (siteInfo && siteInfo.conf) || {}, val = k => c[k] && c[k].from === "screen" ? c[k].value : "", last = Math.max(o.sent || 0, o.pulled || 0), on = !!(o.push || o.link);
