/* ---------- the error log ---------- */
let errLog = null, errSent = 0; const errSeen = new Set();
const browserName = () => { const u = navigator.userAgent, m = u.match(/(Edg|OPR|Firefox|CriOS|FxiOS|Chrome|Version)\/(\d+)/) || [], n = {Edg: "Edge", OPR: "Opera", CriOS: "Chrome", FxiOS: "Firefox", Version: "Safari"}[m[1]] || m[1] || "Browser";
  const os = /iPad|Macintosh.*Mobile/.test(u) || (navigator.maxTouchPoints > 1 && /Macintosh/.test(u)) ? "iPad" : /iPhone/.test(u) ? "iPhone" : /Android/.test(u) ? "Android" : /Windows/.test(u) ? "Windows" : /Mac OS X/.test(u) ? "Mac" : /CrOS/.test(u) ? "Chromebook" : /Linux/.test(u) ? "Linux" : "";
  return n + (m[2] ? " " + m[2] : "") + (os ? " on " + os : ""); };
function errReport(msg, where){
  try{
    if(window.claude || typeof acct !== "function" || !acct()) return; msg = String(msg || "").slice(0, 400);
    if(!msg || /^Script error\.?$|ResizeObserver loop|Failed to fetch|NetworkError|Load failed|AbortError/i.test(msg)) return;   // nothing useful, or just a dropped connection
    const key = msg + "|" + where; if(errSeen.has(key) || errSent >= 8) return; errSeen.add(key); errSent++;
    fetch("auth.php?a=errlog", {method: "POST", headers: {"Content-Type": "application/json"}, credentials: "same-origin", keepalive: true, body: JSON.stringify({msg, where: String(where || "").slice(0, 120), page: typeof view === "string" ? view : "", browser: browserName()})}).catch(() => {});
    errLog = null;
  }catch{}
}
addEventListener("error", e => { if(!e || !e.message) return; errReport(e.message, (e.filename ? e.filename.split("/").pop().split("?")[0] : "") + (e.lineno ? ":" + e.lineno + ":" + (e.colno || 0) : "")); });
addEventListener("unhandledrejection", e => { const r = e && e.reason; if(!r || (typeof r === "object" && r.code && !r.message)) return; errReport(r.message || String(r), r.stack ? (String(r.stack).split("\n")[1] || "").trim().replace(/^at /, "").replace(/https?:\/\/[^/]+\//g, "").slice(0, 120) : ""); });
async function errLoad(clear){ try{ const j = await authCall(clear ? "errclear" : "errors"); errLog = j.errors || []; }catch{ errLog = []; } if(view !== "settings") return; const el = document.getElementById("stErrors"); if(el && stTab !== "todo" && typeof mzSec === "function"){ const t = document.createElement("div"); t.innerHTML = errSection(mzSec); if(t.firstElementChild){ el.innerHTML = t.firstElementChild.innerHTML; return; } } renderSettings(); }   // only this section is redrawn, so a box open elsewhere on the page stays open
function errSection(sec){
  if(window.claude || !(typeof me !== "undefined" && me && me.role === "superadmin")) return "";
  const sub = "Things that went wrong for anyone on the site, newest first. What the page was doing, never what was typed, and no learner work.";
  if(errLog === null){ errLoad(); return sec("stErrors", "Error log", sub, `<p class="small text-body-secondary mb-0">Loading...</p>`); }
  const kind = {browser: ["In the browser", "text-bg-light border"], server: ["On the server", "text-bg-danger"], claude: ["Crafticulum AI", "text-bg-warning"], email: ["Email", "text-bg-warning"], backup: ["Backup", "text-bg-warning"]};
  const when = t => { const d = new Date(t * 1000); return d.toLocaleDateString("en-GB", {day: "numeric", month: "short"}) + ", " + d.toLocaleTimeString("en-GB", {hour: "2-digit", minute: "2-digit"}); };
  const week = errLog.filter(x => x.at > Date.now() / 1000 - 7 * 86400).length;
  return sec("stErrors", "Error log", sub, errLog.length ? `
    <p class="small mb-2"><b>${week}</b> in the last 7 days, ${errLog.length} kept${errLog.length >= 200 ? " (the newest 200 are shown)" : ""}. If the same line keeps coming up, copy it into a message to whoever looks after the site.</p>
    <div class="table-responsive err-wrap"><table class="table table-sm align-middle mb-0 err-t"><thead><tr><th>When</th><th>Where</th><th>What went wrong</th><th>Who and what on</th></tr></thead><tbody>
    ${errLog.map(x => { const k = kind[x.kind] || [x.kind || "Other", "text-bg-light border"]; return `<tr><td class="text-nowrap">${when(x.at)}</td><td><span class="badge ${k[1]} fw-normal">${esc(k[0])}</span>${x.page ? `<div class="small text-body-secondary">${esc(x.page)} page</div>` : ""}</td><td><div class="err-m">${esc(x.msg || "")}</div>${x.where ? `<code class="small">${esc(x.where)}</code>` : ""}</td><td class="small text-body-secondary">${esc([x.role === "superadmin" ? "Super admin" : x.role === "owner" ? "Institution manager" : x.role === "hod" ? "Head of department" : x.role === "teacher" ? "Teacher" : "", x.dept].filter(Boolean).join(", "))}${x.browser ? `<div>${esc(x.browser)}</div>` : ""}</td></tr>`; }).join("")}
    </tbody></table></div>
    <div class="d-flex flex-wrap gap-2 mt-3"><button type="button" class="btn btn-sm btn-outline-secondary" data-err="load">Check again</button><button type="button" class="btn btn-sm btn-outline-secondary" data-err="copy">Copy the list</button><button type="button" class="btn btn-sm btn-outline-danger" data-err="clear">Clear the log</button></div>`
    : `<p class="small mb-2">Nothing has gone wrong. Errors in anyone's browser, on the server, from Crafticulum AI, from email and from backups are listed here when they happen.</p><button type="button" class="btn btn-sm btn-outline-secondary" data-err="load">Check again</button>`);
}
