  const fld = (id, label, ph, extra) => `<div class="col-md-6"><label class="form-label" for="mk_${id}">${label}</label>${extra && extra.before || ""}<input class="form-control form-control-sm" id="mk_${id}" data-mkf="${id}" ${extra && extra.type ? `type="${extra.type}"` : ""} placeholder="${esc(ph)}" value="${esc(s.f[id])}" autocomplete="off">${extra && extra.after || ""}</div>`;
  const lm = [["named", s.batch.on ? "Use their names" : "Enter their details", s.batch.on ? "Each learner's name and ID go on their record, the file names and the email." : "Name and ID go on the record, the file names and the email."], ["anon", s.batch.on ? "Keep them anonymous" : "Keep it anonymous", s.batch.on ? "Each learner gets a reference in place of a name." : "No name, ID or email is entered. The work gets a reference."]].filter(m => !(s.forceAnon && m[0] === "named"));
