/* ===== round 27: plain names for the documents students make ===== */
/* documents students make get plain names that match the lesson, and task steps are whole sentences */
const DOC_RULES = `- Number the tasks in order and start each task title with its number: "Task 1: ...", "Task 2: ...". Use the same numbers wherever a task is mentioned, so students can find their place again.
- Write every task step as one full, plain sentence that says what to do, what to use and what to end up with. No note form, no code-like labels.
- When a step asks students to make or save a document, give it a plain name that matches this lesson: the unit number, the task number and what it is, then their own name. For example: Create a Word document and save it as "Unit 3 Task 2 Research analysis" followed by your name. Never use underscores, letter codes or the word Surname in a document name (never anything like B_Analysis_Surname). Use the same name every time that document is mentioned, including in the checklist and the independent study.
`;
const _buildPrompt31 = buildPrompt;
buildPrompt = function(){ let p = _buildPrompt31.apply(this, arguments); try{ const at = "- doneBy: 2 to 4 short checklist items."; if(p.includes(at)) p = p.replace(at, DOC_RULES + at); }catch(e){ console.error(e); } return p; };
/* lessons built before this: a document name like B_Analysis_Surname reads as "B Analysis (your surname)" */
const NAME_SEG = /^(your)?(sur|first|last|full|student)name$|^(your)?initials$/i;
function plainDocNames(s){ if(typeof s !== "string" || s.indexOf("_") < 0) return s;
  return s.replace(/\b[A-Za-z0-9]+(?:_[A-Za-z0-9]+)+\b/g, (tok, at, all) => { const parts = tok.split("_"), got = [];
    while(parts.length > 1 && NAME_SEG.test(parts[parts.length - 1])) got.push(parts.pop());
    if(!got.length) return tok; const who = got.some(l => /initials/i.test(l)) ? "your initials" : got.length === 1 && /^(your)?(sur|last)name$/i.test(got[0]) ? "your surname" : "your name";
    if(!/\b(file|document|doc|folder|save|saved|presentation|spreadsheet|workbook|word|powerpoint|excel|slides?|report)\b/i.test(all.slice(Math.max(0, at - 90), at))) return tok;
    return parts.join(" ") + " (" + who + ")"; }); }
function plainDocWalk(o, depth){ if(!o || typeof o !== "object" || depth > 6) return; for(const k of Object.keys(o)){ if(k === "id" || k === "meta" || k === "visual" || k === "image" || k === "diagram") continue; const v = o[k]; if(typeof v === "string"){ const n = plainDocNames(v); if(n !== v) o[k] = n; } else if(v && typeof v === "object") plainDocWalk(v, (depth || 0) + 1); } }
const _showLesson31 = showLesson;
showLesson = function(L){ try{ if(L && typeof L === "object") ["steps", "doneBy", "howTo", "tasks", "study", "teach", "starter"].forEach(k => { if(Array.isArray(L[k])) L[k] = L[k].map(x => typeof x === "string" ? plainDocNames(x) : (plainDocWalk(x, 0), x)); else plainDocWalk(L[k], 0); }); }catch(e){ console.error(e); } return _showLesson31.apply(this, arguments); };

