/* ===== round 35: notifications on your own devices. The server sends the ones that come from other people; this page raises the ones about its own work when you're looking elsewhere ===== */
let pushInfo = null, pushBusy = false, pushHere = null, pushMsg = "", pushErr = false;
const pushCan = () => !window.claude && "serviceWorker" in navigator && "PushManager" in window && "Notification" in window;
const pushIos = () => /iPad|iPhone|iPod/.test(navigator.userAgent) || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
const pushKey = k => { const s = atob(k.replace(/-/g, "+").replace(/_/g, "/") + "=".repeat((4 - k.length % 4) % 4)); return Uint8Array.from(s, c => c.charCodeAt(0)); };
const pushDevice = () => { const u = navigator.userAgent, os = /iPhone/.test(u) ? "iPhone" : /iPad/.test(u) || pushIos() ? "iPad" : /Android/.test(u) ? "Android" : /Windows/.test(u) ? "Windows" : /Mac OS X/.test(u) ? "Mac" : /CrOS/.test(u) ? "Chromebook" : /Linux/.test(u) ? "Linux" : "Device", br = /Edg\//.test(u) ? "Edge" : /Firefox\//.test(u) ? "Firefox" : /Chrome\//.test(u) ? "Chrome" : /Safari\//.test(u) ? "Safari" : "browser"; return os + ", " + br; };
const pushId = async ep => { try{ const h = await crypto.subtle.digest("SHA-1", new TextEncoder().encode(ep)); return [...new Uint8Array(h)].map(b => b.toString(16).padStart(2, "0")).join("").slice(0, 12); }catch{ return ""; } };
async function pushLoad(){ if(pushBusy) return; pushBusy = true;
  try{ pushInfo = await authCall("pushget"); pushHere = null;
    if(pushCan()){ const reg = await Promise.race([navigator.serviceWorker.ready, new Promise(r => setTimeout(() => r(null), 2500))]); const sub = reg && await reg.pushManager.getSubscription(); if(sub){ const id = await pushId(sub.endpoint); pushHere = pushInfo.devices.some(d => d.id === id) ? id : null; } } }
  catch{ pushInfo = pushInfo || {failed: true}; }
  finally{ pushBusy = false; if(view === "settings") renderSettings(); if(pushHere) pushDatesSync(); } }
const pushSay = (t, bad) => { pushMsg = t; pushErr = !!bad; if(view === "settings") renderSettings(); setTimeout(() => { if(pushMsg === t){ pushMsg = ""; if(view === "settings") renderSettings(); } }, 7000); };
async function pushOn(){
  try{ if(!pushInfo || !pushInfo.key) return pushSay("This site can't send notifications yet.", true);
    const perm = await Notification.requestPermission(); if(perm !== "granted") return pushSay(perm === "denied" ? "Notifications are blocked for this site in your browser. Allow them in the browser's site settings, then try again." : "Notifications weren't allowed, so nothing was switched on.", true);
    const reg = await navigator.serviceWorker.ready; let sub = await reg.pushManager.getSubscription();
    if(sub){ const k = sub.options && sub.options.applicationServerKey ? btoa(String.fromCharCode(...new Uint8Array(sub.options.applicationServerKey))).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "") : ""; if(k && k !== pushInfo.key){ await sub.unsubscribe(); sub = null; } }
    if(!sub) sub = await reg.pushManager.subscribe({userVisibleOnly: true, applicationServerKey: pushKey(pushInfo.key)});
    const j = await authCall("pushsub", {sub: sub.toJSON(), ua: pushDevice()}); pushInfo = j; pushHere = j.this || null; pushSay("Notifications are on for this device."); pushDatesSync(true);
  }catch(e){ console.error(e); pushSay("Couldn't switch notifications on here. Try again.", true); } }
async function pushOff(id){
  try{ let ep = ""; if(id === pushHere && pushCan()){ const reg = await navigator.serviceWorker.ready, sub = await reg.pushManager.getSubscription(); if(sub){ ep = sub.endpoint; await sub.unsubscribe().catch(() => {}); } }
    pushInfo = await authCall("pushunsub", {id, endpoint: ep}); if(id === pushHere) pushHere = null; pushSay(id ? "Switched off for that device." : "Switched off.");
  }catch{ pushSay("Couldn't switch that off. Try again.", true); } }
/* assignment dates for the next ten weeks, as this person's own planning shows them, so the server can remind on the right days */
function pushDatesList(){ const out = [], seen = new Set(), from = todayIso(), to = addDays(from, 70);
  try{ UNITS.forEach(L => (L.u || []).forEach(u => unitDues(L.s, L, u).forEach(x => { [["out", x.out], ["due", x.due], ["resub", x.resub]].forEach(([k, d]) => { if(!d || d < from || d > to) return; const id = x.b.id + "|" + k + "|" + d; if(seen.has(id)) return; seen.add(id); out.push({d, k, t: x.b.a, u: String(u.t || "").replace(/:.*/, "")}); }); }))); }catch(e){ console.error(e); }
  return out.sort((a, b) => a.d < b.d ? -1 : 1).slice(0, 300); }
let pushDatesT = 0;
function pushDatesSync(force){ if(!pushHere || window.claude) return; clearTimeout(pushDatesT); pushDatesT = setTimeout(() => { try{ const items = pushDatesList(), sig = JSON.stringify(items) + "|" + todayIso(); if(!force && lsGet("cc_push_dates") === sig) return; authCall("pushdates", {items}).then(() => lsSet("cc_push_dates", sig)).catch(() => {}); }catch{} }, force ? 300 : 4000); }
const _saveAsg38 = saveAsg;
saveAsg = function(){ const r = _saveAsg38.apply(this, arguments); try{ pushDatesSync(); }catch{} return r; };
/* work this page finished while you were looking at something else */
async function localNotify(kind, title, body){
  try{ if(window.claude || !pushHere || !pushInfo || !pushInfo.prefs || !pushInfo.prefs[kind] || !document.hidden || Notification.permission !== "granted") return false;
    const reg = await navigator.serviceWorker.ready; await reg.showNotification(title, {body: body || "", icon: "icon-192.png", badge: "favicon-32.png", tag: "local-" + kind, data: {url: ""}}); return true; }catch{ return false; } }
const _buildLesson38 = buildLesson;
buildLesson = async function(){ const r = await _buildLesson38.apply(this, arguments); try{ if(!batch.running) localNotify("builds", "Your lesson is ready", (r && r.title) || ""); }catch{} return r; };
let batchWas = false;
const _drawBatch38 = drawBatch;
drawBatch = function(){ const r = _drawBatch38.apply(this, arguments); try{ if(batchWas && !batch.running && batch.total) localNotify("builds", batch.done === 1 ? "1 lesson built" : batch.done + " lessons built", batch.failed ? batch.failed + " couldn't be built. Open Planning to try them again." : "The whole set is ready in Planning."); batchWas = batch.running; }catch{} return r; };
let mkWas = "";
setInterval(() => { try{ if(typeof markerSM === "undefined" || !markerSM || !markerSM.run) return; const s = markerSM.run("aiState"); if(mkWas === "running" && s === "done") localNotify("builds", "Second Marker has finished", "The check is ready for you to go through."); if(mkWas === "running" && s === "error") localNotify("builds", "Second Marker couldn't finish", "Open it to see what went wrong."); mkWas = s; }catch{} }, 2000);
try{ ST_GROUPS.find(g => g[0] === "you")[2].push("stNotify"); }catch{}
const PUSH_KINDS = [["builds", "When something finishes", "A lesson, a set of lessons or a Second Marker check that finishes while you're on another tab or app.", () => true],
  ["dates", "Assignment dates", "The day before and on the day an assignment is handed out, is due in, or has resubmissions due.", () => true],
  ["review", "Comments and sign-off", "A comment on your lesson, a change waiting for your sign-off, or your change being signed off.", () => true],
  ["people", "People and messages", "Someone waiting for you to approve their account, and messages from the contact page.", () => !!me.canTeam || me.role === "superadmin"],
  ["plan", "Plan and payments", "Nearly at this month's limit, at it, or a payment that didn't go through.", () => me.role === "owner" && !!(meInfo && meInfo.billing)]];
function notifySection(sec){
  if(window.claude || !me || me.demo) return "";
  if(!pushInfo){ pushLoad(); return sec("stNotify", "Notifications", "", `<p class="small text-body-secondary mb-0">Loading...</p>`); }
  const can = pushCan(), ok = !pushInfo.failed && pushInfo.ok, others = (pushInfo.devices || []).filter(d => d.id !== pushHere), blocked = can && Notification.permission === "denied";
  const state = pushInfo.failed ? `<p class="small mb-2">Couldn't load your notification settings just now.</p><button type="button" class="btn btn-sm btn-outline-secondary" data-push="retry">Try again</button>`
    : !ok ? `<div class="alert alert-secondary small mb-0">This server can't send notifications yet. It needs PHP's OpenSSL and cURL switched on, which your web host can do.</div>`
    : !can ? `<div class="alert alert-info small mb-0">${pushIos() ? "On an iPhone or iPad, add Crafticulum to your Home Screen first: press Share, then Add to Home Screen. Open it from there and come back to this page to switch notifications on." : "This browser can't show notifications from websites. Try Chrome, Edge, Firefox or Safari, on a page that starts https."}</div>`
    : pushHere ? `<div class="d-flex flex-wrap gap-2 align-items-center"><span class="badge text-bg-success">On for this device</span><span class="small text-body-secondary">${esc(pushDevice())}</span><button type="button" class="btn btn-sm btn-outline-primary ms-auto" data-push="test">Send a test</button><button type="button" class="btn btn-sm btn-outline-secondary" data-push="off" data-id="${esc(pushHere)}">Turn off here</button></div>`
    : `<div class="d-flex flex-wrap gap-3 align-items-center"><button type="button" class="btn btn-primary" data-push="on" ${blocked ? "disabled" : ""}>Turn on notifications on this device</button><span class="small text-body-secondary">${blocked ? "Notifications are blocked for this site in your browser. Allow them in the browser's site settings first." : "Your browser will ask you to allow them."}</span></div>`;
  return sec("stNotify", "Notifications", "A nudge on this phone, tablet or computer when something needs you or has finished. Each device is switched on separately, and a notification never contains learner work.", `
    ${state}
    ${pushMsg ? `<div class="idea-msg mt-2${pushErr ? " err" : ""}" role="status">${esc(pushMsg)}</div>` : ""}
    ${ok ? `<h3 class="h6 mt-4 mb-2">What to tell you about</h3><div class="push-kinds">${PUSH_KINDS.filter(k => k[3]()).map(([k, t, d]) => `<div class="form-check form-switch push-k"><input class="form-check-input" type="checkbox" role="switch" id="pk-${k}" data-pushk="${k}" ${pushInfo.prefs[k] ? "checked" : ""}><label class="form-check-label" for="pk-${k}"><span class="fw-semibold">${t}</span><span class="d-block small text-body-secondary">${d}</span></label></div>`).join("")}</div>
    <div class="form-text">Assignment reminders use the dates in your planning${pushInfo.dates ? `: ${pushInfo.dates} coming up in the next ten weeks` : ""}. They are sent after 7 in the morning.</div>` : ""}
    ${others.length ? `<h3 class="h6 mt-4 mb-2">Your other devices</h3><ul class="list-unstyled small mb-0 push-dev">${others.map(d => `<li><span>${esc(d.ua || "A device")} <span class="text-body-secondary">· switched on ${d.added ? new Date(d.added * 1000).toLocaleDateString("en-GB", {day: "numeric", month: "short", year: "numeric"}) : ""}</span></span><button type="button" class="btn btn-sm btn-link text-danger p-0" data-push="off" data-id="${esc(d.id)}">Turn off</button></li>`).join("")}</ul>` : ""}
    ${pushInfo.cron ? `<details class="conf-g mt-3"><summary>Make the morning reminders reliable (super admin)</summary><p class="small text-body-secondary mb-2">Assignment reminders go out the first time anyone opens the site after 7am. To send them even on a day nobody signs in, ask your web host's scheduled jobs (cron) to open this address once a day, a little after 7am:</p><div class="input-group input-group-sm"><input class="form-control" id="pushCron" readonly value="${esc(pushInfo.cron)}" aria-label="Address for the scheduled job"><button type="button" class="btn btn-outline-secondary" data-push="copycron">Copy</button></div></details>` : ""}`);
}
