document.addEventListener("click", async e => { const b = e.target.closest("[data-push]"); if(!b) return; const k = b.dataset.push;
  if(k === "retry"){ pushInfo = null; return renderSettings(); }
  if(k === "on"){ b.disabled = true; return pushOn(); }
  if(k === "off") return pushOff(b.dataset.id);
  if(k === "copycron"){ try{ await navigator.clipboard.writeText($("#pushCron").value); pushSay("Copied."); }catch{ $("#pushCron").select(); } return; }
  if(k === "test"){ b.disabled = true; try{ const j = await authCall("pushtest"); pushSay(j.sent ? "Sent. It should appear in a moment." : "The test couldn't be delivered to this device. Turn notifications off here and on again.", !j.sent); if(!j.sent) pushLoad(); }catch{ pushSay("Couldn't send the test. Try again.", true); } } });
