/* ---------- one press from a handed-in file to Second Marker. The file is fetched into this page's memory and handed over: nothing new is stored ---------- */
const lnMarkOk = () => typeof markerNow === "function" && !!(acct() && markerNow().can);
async function lnCheck(code, id, name, orig){
  if(!lnMarkOk()) return toast("Second Marker isn't switched on for you.", {bad: true});
  if(!/\.(pdf|docx)$/i.test(orig)) return toast("Second Marker reads PDF and Word (.docx) files. Download this one instead.", {bad: true});
  try{ toast("Fetching the work...");
    const r = await fetch(`handin.php?a=get&c=${encodeURIComponent(code)}&f=${encodeURIComponent(id)}`, {credentials: "same-origin"}); if(!r.ok) throw 0;
    const blob = await r.blob(), file = new File([blob], orig, {type: /\.pdf$/i.test(orig) ? "application/pdf" : "application/vnd.openxmlformats-officedocument.wordprocessingml.document"});
    setView("marker"); for(let i = 0; i < 100 && !markerSM; i++) await new Promise(ok => setTimeout(ok, 200)); if(!markerSM) throw 0;
    await new Promise(ok => setTimeout(ok, 300)); window.__mkFile = file; window.__mkHandin = {name, orig, at: Date.now()};
    markerSM.run("handleFile(window.__mkFile)"); try{ if(typeof mkNativeTick === "function") mkNativeTick(); }catch{}
    toast(`${name}'s work is loaded into Second Marker. Pick the unit and assignment if you haven't, then run the check.`);
  }catch{ toast("Couldn't load that into Second Marker. Download it and add it there instead.", {bad: true}); }
}
document.addEventListener("click", e => { const b = e.target.closest('[data-ln="check"]'); if(!b) return; const li = b.closest("[data-code]"); if(li) lnCheck(li.dataset.code, b.dataset.f, b.dataset.n, b.dataset.o); });
