lnHandHtml = function(){ let h = _lnHandHtml43.apply(this, arguments); if(!lnMarkOk() || !lnLinks) return h;
  lnLinks.forEach(l => l.files.forEach(f => { if(!/\.(pdf|docx)$/i.test(f.orig)) return; const dl = `href="handin.php?a=get&amp;c=${esc(l.code)}&amp;f=${esc(f.id)}" download>Download</a>`; h = h.replace(dl, dl + ` <button type="button" class="btn btn-sm btn-primary" data-ln="check" data-f="${esc(f.id)}" data-n="${esc(f.name)}" data-o="${esc(f.orig)}">Check in Second Marker</button>`); }));
  return h.replace("Download it to mark it, or to check it in Second Marker.", "Download it to mark it, or press Check in Second Marker to load a PDF or Word file straight in."); };

