  (Array.isArray(L.teach) ? L.teach : []).forEach(t => { if(!t || !t.title) return; sec.push(["Teach: " + t.title, [t.explain, li(t.points), (t.terms || []).length ? "| Term | Meaning |\n|---|---|\n" + t.terms.map(x => `| ${cell(Array.isArray(x) ? x[0] : x.term || x.t || x)} | ${cell(Array.isArray(x) ? x[1] : x.meaning || x.d || "")} |`).join("\n") : "", t.example && "**Example:** " + t.example, t.ask && "**Ask:** " + t.ask + (t.answer ? " (" + t.answer + ")" : "")].filter(Boolean).join("\n\n")]); });
  (Array.isArray(L.tasks) ? L.tasks : []).forEach((t, i) => { if(!t || !t.title) return; sec.push([`Task ${i + 1}: ${t.title}`, [t.goal, (t.steps || []).map((s, k) => `${k + 1}. ${String(s).replace(/\n/g, " ")}`).join("\n"), (t.check || []).length ? "**Success criteria**\n\n" + li(t.check) : "", t.tip && "**Tip:** " + t.tip, t.stretch && "**Stretch:** " + t.stretch].filter(Boolean).join("\n\n")]); });
  if(Array.isArray(L.quiz) && L.quiz.length) sec.push(["Exit quiz", L.quiz.map((q, i) => `${i + 1}. ${String(q.q).replace(/\n/g, " ")}\n${(q.options || []).map((x, k) => `   ${String.fromCharCode(65 + k)}. ${x}`).join("\n")}`).join("\n") + "\n\n**Answers:** " + L.quiz.map((q, i) => `${i + 1} ${String.fromCharCode(65 + (Number(q.answer) || 0))}`).join(", ")]);
  if(L.stretch || L.support) sec.push(["Stretch and support", [L.stretch && "**Stretch:** " + L.stretch, L.support && "**Support:** " + L.support].filter(Boolean).join("\n\n")]);
