function eduTarget(who){ if(who === "dept") return courseCfg.ctx || (courseCfg.ctx = {}); const list = (courseCfg.list || []).filter(courseOk), x = list[+who]; if(!x) return null; if(!x.ctx) x.ctx = {...JSON.parse(JSON.stringify(eduDept() || {})), verified: null, qual: ((x.src || [])[0] || {}).qualification || ""}; return x.ctx; }
