  box.querySelectorAll("[data-also-d]").forEach(c => { if(c.checked){ const r = box.querySelector(`[data-also-r="${c.dataset.alsoD}"]`); also[c.dataset.alsoD] = r && r.value === "hod" ? "hod" : "teacher"; } });
