function splitDraw(){ const s = $("#stDepts"); if(!s || !me || me.role !== "superadmin" || me.inside === false || window.claude) return; const body = s.querySelector(".card-body"); if(!body) return; const old = body.querySelector("#splitBox"), h = splitHtml(); if(old) old.remove(); if(h) body.insertAdjacentHTML("beforeend", h); }
function splRead(){ const n = $("#splName"), k = $("#splKeep"); if(n) spl.name = n.value.trim(); if(k) spl.keep = k.value.trim(); }
document.addEventListener("change", e => { const t = e.target; if(!t.dataset || !t.dataset.splS) return; splRead(); const all = [...new Set(splUnits().map(u => u.s))]; spl.subs = [...document.querySelectorAll("[data-spl-s]:checked")].map(x => x.dataset.splS); const rest = all.filter(n => !spl.subs.includes(n));
  if(!spl.name || all.includes(spl.name)) spl.name = spl.subs.length === 1 ? spl.subs[0] : spl.name; if(!spl.keep || all.includes(spl.keep) || spl.keep === me.deptName) spl.keep = rest.length === 1 ? rest[0] : (spl.keep || me.deptName || ""); spl.plan = null; spl.arm = false; splitDraw(); });
document.addEventListener("click", async e => { const b = e.target.closest("[data-spl]"); if(!b || spl.busy) return; const k = b.dataset.spl; splRead();
  if(k === "open"){ spl.open = true; spl.msg = ""; if(!spl.keep) spl.keep = me.deptName || ""; return splitDraw(); } if(k === "close"){ spl = {...spl, open: false, plan: null, arm: false, msg: ""}; return splitDraw(); }
  const body = {dept: me.dept, subjects: spl.subs, name: spl.name, keepName: spl.keep, units: splUnits().map(u => ({s: u.s, l: u.l, u: u.u}))};
  if(k === "go" && !spl.arm){ spl.arm = true; splitDraw(); setTimeout(() => { if(spl.arm){ spl.arm = false; splitDraw(); } }, 6000); return; }
  spl.busy = true; spl.bad = false; spl.msg = k === "undo" ? "Putting it back..." : k === "go" ? "Splitting. Keep this page open." : "Working it out..."; splitDraw();
  try{ if(k === "preview"){ if(!spl.name) throw {code: "name"}; const j = await authCall("deptsplit", body); spl.plan = j.plan; spl.msg = ""; }
    else if(k === "go"){ const j = await authCall("deptsplit", {...body, go: true}); try{ ["cc_depts", "cc_hd_dept"].forEach(x => localStorage.removeItem(x)); ACCOUNT_KEYS.forEach(x => localStorage.removeItem(x)); }catch{} lsSet("cc_flash", `${j.plan.newName} is now its own department. ${j.plan.keepName} keeps ${j.plan.staying.join(", ")}.`); return location.reload(); }
    else if(k === "undo"){ const j = await authCall("deptsplitundo"); try{ ["cc_depts", "cc_hd_dept"].forEach(x => localStorage.removeItem(x)); ACCOUNT_KEYS.forEach(x => localStorage.removeItem(x)); }catch{} lsSet("cc_flash", `Undone. ${j.undone} has been folded back in.`); return location.reload(); } }
  catch(err){ const c = err && err.code; spl.bad = true; spl.msg = c === "none" ? "There's no split to undo." : c === "name" ? "Give the new department a name." : c === "all" ? "Leave at least one subject behind." : c === "subjects" ? "Pick the subjects that move." : "That didn't work. Nothing was changed."; }
  spl.busy = false; spl.arm = false; splitDraw(); });
