/* ===== round 71 (v121): star one of Crafti's replies and it goes onto a blank board: full screen, big type, ready for the class. It's copied as well,
   and an Open the board button appears. The board can be typed on, made bigger or smaller, and keeps the last few things you starred. ===== */
let cbList = [], cbAt = 0, cbSize = 1;
try{ const j = JSON.parse(lsGet("cc_boards") || "[]"); if(Array.isArray(j)) cbList = j.filter(x => x && x.html).slice(0, 12); cbSize = +(lsGet("cc_board_size") || 1) || 1; }catch{}
const cbKeep = () => { try{ lsSet("cc_boards", JSON.stringify(cbList.slice(0, 12))); }catch{} };
const cbHas = key => cbList.some(x => x.key === key);
const CB_STAR = on => `<svg viewBox="0 0 24 24" width="16" height="16" fill="${on ? "currentColor" : "none"}" stroke="currentColor" stroke-width="2" stroke-linejoin="round" aria-hidden="true"><path d="M12 3l2.7 5.6 6.1.9-4.4 4.3 1 6.1L12 17l-5.4 2.9 1-6.1L3.200 9.5l6.1-.9z"/></svg>`;
function cbStar(c, i){ const m = c && c.msgs[i]; if(!m) return; const key = c.id + ":" + i, at = cbList.findIndex(x => x.key === key);
  if(at >= 0){ cbList.splice(at, 1); cbKeep(); return false; }
  const q = c.msgs.slice(0, i).reverse().find(x => x.r === "u"); cbList.unshift({key, title: String((q && q.t) || "From Crafti").replace(/\s+/g, " ").trim().slice(0, 90), html: tkClean(tkMd(m.t)), text: m.t, at: Date.now()}); cbList = cbList.slice(0, 12); cbAt = 0; cbKeep();
  try{ navigator.clipboard.writeText(m.t).catch(() => {}); }catch{} return true; }
function cbOpen(key){ if(!cbList.length) return; if(key){ const i = cbList.findIndex(x => x.key === key); if(i >= 0) cbAt = i; } cbAt = Math.max(0, Math.min(cbList.length - 1, cbAt)); let el = $("#cfBoard");
  if(!el){ el = document.createElement("div"); el.id = "cfBoard"; el.setAttribute("role", "dialog"); el.setAttribute("aria-modal", "true"); el.setAttribute("aria-label", "Board"); document.body.appendChild(el); }
  const b = cbList[cbAt], many = cbList.length > 1; el.dataset.from = el.dataset.from || "";
  el.innerHTML = `<div class="cb-bar"><span class="cb-t">${esc(b.title)}</span>${many ? `<button type="button" class="cb-b" data-cb="prev" aria-label="Previous starred reply">&lsaquo;</button><span class="cb-n">${cbAt + 1} of ${cbList.length}</span><button type="button" class="cb-b" data-cb="next" aria-label="Next starred reply">&rsaquo;</button>` : ""}<button type="button" class="cb-b" data-cb="smaller" aria-label="Smaller text">A&minus;</button><button type="button" class="cb-b" data-cb="bigger" aria-label="Bigger text">A+</button><button type="button" class="cb-b" data-cb="copy">Copy</button><button type="button" class="cb-b" data-cb="clear">Clear</button><button type="button" class="cb-b cb-x" data-cb="close" aria-label="Close the board">&times;</button></div>
    <div class="cb-page tk-body" id="cbPage" contenteditable="true" spellcheck="false" aria-label="Board. You can type on it." style="font-size:${cbSize}em">${b.html}</div><div class="cb-foot">You can type on the board. Escape closes it.</div>`;
  document.documentElement.style.overflow = "hidden"; const x = el.querySelector('[data-cb="close"]'); if(x) x.focus(); }
function cbClose(){ const el = $("#cfBoard"); if(!el) return; const p = $("#cbPage"), b = cbList[cbAt]; if(p && b){ b.html = tkClean(p.innerHTML); cbKeep(); } el.remove(); document.documentElement.style.overflow = ""; const o = document.querySelector("[data-cb-open]"); if(o) o.focus(); }
document.addEventListener("click", e => { const t = e.target;
  const st = t.closest("[data-cb-star]"); if(st){ const c = st.dataset.asChat ? asChat() : cfChat(), on = cbStar(c, +st.dataset.i); if(on === undefined) return; toast(on ? "On the board, and copied." : "Taken off the board."); if(st.dataset.asChat) asDraw(); else cfDraw(false); return; }
  const op = t.closest("[data-cb-open]"); if(op) return cbOpen(op.dataset.cbOpen);
  const b = t.closest("[data-cb]"); if(!b) return; const k = b.dataset.cb, p = $("#cbPage"), cur = cbList[cbAt];
  if(k === "close") return cbClose();
  if(k === "prev" || k === "next"){ if(p && cur){ cur.html = tkClean(p.innerHTML); cbKeep(); } cbAt = (cbAt + (k === "next" ? 1 : -1) + cbList.length) % cbList.length; return cbOpen(); }
  if(k === "bigger" || k === "smaller"){ cbSize = Math.max(.7, Math.min(2.6, Math.round((cbSize + (k === "bigger" ? .15 : -.15)) * 100) / 100)); lsSet("cc_board_size", String(cbSize)); if(p) p.style.fontSize = cbSize + "em"; return; }
  if(k === "copy"){ try{ navigator.clipboard.writeText(p ? p.innerText : "").then(() => { b.textContent = "Copied"; setTimeout(() => { b.textContent = "Copy"; }, 1500); }).catch(() => {}); }catch{} return; }
  if(k === "clear"){ if(p){ p.innerHTML = "<p><br></p>"; p.focus(); } return; } });
document.addEventListener("keydown", e => { if(e.key === "Escape" && $("#cfBoard")){ e.preventDefault(); e.stopPropagation(); cbClose(); } }, true);
/* the star and Open the board, under each reply: in the chat window and on the Crafti page */
const cbBtns = (c, i, big) => { const on = c && cbHas(c.id + ":" + i), cls = big ? "btn btn-sm btn-outline-primary" : "cf-act", ex = big ? ' data-as-chat="1"' : ""; return `<button type="button" class="${cls} cb-star${on ? " on" : ""}" data-cb-star data-i="${i}"${ex} aria-pressed="${on}" title="Put this on a blank board for the class">${CB_STAR(on)} ${on ? "On the board" : "Board"}</button>${on ? `<button type="button" class="${cls} cb-open" data-cb-open="${esc(c.id + ":" + i)}">Open the board</button>` : ""}`; };
const _cfMsgs71 = cfMsgs;
cfMsgs = function(){ const c = cfChat(); return _cfMsgs71.apply(this, arguments).replace(/<button type="button" class="btn btn-link btn-sm p-0" data-cf-copy="(\d+)">/g, (m, i) => cbBtns(c, +i, false) + m); };
const _asHtml71 = asHtml;
asHtml = function(){ const c = asChat(); return _asHtml71.apply(this, arguments).replace(/(<button type="button" class="btn btn-sm btn-outline-primary" data-as="doc" data-i="(\d+)">)/g, (m, b, i) => cbBtns(c, +i, true) + b); };

/* ===== round 72 (v122): the class results on the board show every question that caught the class out (up to three), the answer most hands went to by mistake,
   and tips for getting them all right. Hands up is counts only, so nobody is named. The quiz room (initials on phones) has its own class view with made-up names. ===== */
function qsMissed(d){ const qz = (d && d.quiz) || [], out = [];
  qz.forEach((q, i) => { const c = (tally[i] || []).slice(0, q.options.length); while(c.length < q.options.length) c.push(0); const tot = c.reduce((a, b) => a + b, 0); if(!tot) return;
    let slip = -1; c.forEach((n, j) => { if(j !== q.answer && n > 0 && (slip < 0 || n > c[slip])) slip = j; });
    const pct = Math.round(c[q.answer] / tot * 100); if(pct < 100) out.push({i, q, c, tot, slip, pct}); });
  return out.sort((a, b) => a.pct - b.pct || a.i - b.i); }
function qsTips(m){ const t = m.slice(0, 3).filter(p => p.q.why).map(p => `Q${p.i + 1}: ${p.q.why}`);
  if(m.some(p => p.slip >= 0 && p.c[p.slip] >= Math.max(2, p.tot / 3))) t.push("Where lots of us picked the same wrong answer, two options were close. Read all of them before you choose, and look for the one word that makes an answer wrong.");
  t.push("Cover the options, say the answer in your own words, then find the option that matches.");
  return t.slice(0, 5); }
const _showSlide72 = showSlide;
showSlide = function(s){ const r = _showSlide72.apply(this, arguments);
  try{ if(s === "quiz" && quizView === "results"){ const B = $("#bBody"), grid = B && B.querySelector(".res-grid"); if(grid && !B.querySelector("#qsTips")){ const m = qsMissed(current), LT = "ABCD";
      const old = B.querySelector(".res-call"); if(old) old.remove();
      const html = (m.length ? `<div id="qsMiss">${m.slice(0, 3).map(p => `<div class="res-call"><b>Q${p.i + 1} caught us out (${p.pct}% right):</b> ${esc(p.q.q)}<br>${p.slip >= 0 ? `<span style="color:var(--chalk-dim)">Most common slip: ${LT[p.slip]}) ${esc(p.q.options[p.slip])}</span><br>` : ""}Answer: <span style="color:var(--chalk-g)">${LT[p.q.answer]}) ${esc(p.q.options[p.q.answer])}</span>${p.q.why ? ` · ${esc(p.q.why)}` : ""}</div>`).join("")}</div>` : `<div class="res-call" id="qsMiss" style="border-color:var(--chalk-g)"><b style="color:var(--chalk-g)">Full marks:</b> every hand went to the right answer.</div>`)
        + `<div class="res-call" id="qsTips" style="border-color:var(--chalk-y)"><b style="color:var(--chalk-y)">How to get them all right next time</b><ol style="margin:.3em 0 0;padding-left:1.3em">${qsTips(m).map(t => `<li>${esc(t)}</li>`).join("")}</ol></div>`;
      grid.insertAdjacentHTML("beforebegin", html); fitBoard($("#bFrame")); } } }catch(e){ console.error(e); }
  return r; };

/* ===== round 73 (v123): Open lesson from Planning or the Library shows the lesson on its own, full width, without the New lesson panel beside it.
   A small bar above it goes back to Planning or brings the panel back. Lessons in the menu and Create a lesson still open the panel as before. ===== */
