document.addEventListener("click", e => { const t = e.target; if(!t || !t.closest) return;
  if(t.closest('[data-sq="open"]')){ lsFocus = true; lsFrom = "seq"; }
  else if(t.closest('[data-ov="open"], #libList [data-open]')){ lsFocus = true; lsFrom = ""; }
  else if(t.closest("[data-lsf]")){ lsFocus = false; render(current); const f = $("#form"); if(f) f.scrollIntoView({block: "nearest"}); }
  else if(t.closest("[data-nav]")) lsFocus = false; }, true);
const lsFocusOn = () => lsFocus && view === "lesson" && !!current && !current.example;
const _setView73 = setView;
