function wnShow(from, to){ const items = WHATS_NEW.filter(x => x[0] > from && x[0] <= to).slice(0, 6); if(!items.length || document.getElementById("wnBox")) return;
  document.body.insertAdjacentHTML("beforeend", `<div class="wn" id="wnBox" role="dialog" aria-labelledby="wnT"><div class="wn-h"><span id="wnT">What's new in Crafticulum</span><button type="button" class="btn-close btn-close-white" data-wn="close" aria-label="Close"></button></div><ul>${items.map(x => `<li><b>${esc(x[1])}</b><span>${esc(x[2])}</span></li>`).join("")}</ul><div class="wn-f"><button type="button" class="btn btn-sm btn-primary" data-wn="close">Got it</button></div></div>`); }
