let bulk = null;
function bulkParse(text){ const depts = (typeof team !== "undefined" && team && team.depts) || [], rows = [], seen = new Set(); let first = true; String(text || "").split(/\r?\n/).forEach(line => { line = line.trim(); if(!line) return; const head = first; first = false; const cells = (line.includes("\t") ? line.split("\t") : line.split(/[,;]/)).map(c => c.trim().replace(/^"|"$/g, "")).filter(c => c !== "");
    const ei = cells.findIndex(c => /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(c.replace(/^.*<|>.*$/g, ""))); if(ei < 0){ if(head && /e-?mail/i.test(line)) return; rows.push({bad: "No email address", raw: line}); return; }
    const email = cells[ei].replace(/^.*<|>.*$/g, "").toLowerCase(), m = /^(.*)</.exec(cells[ei]), rest = cells.filter((c, i) => i !== ei); let name = (m && m[1].trim()) || "", role = "teacher", dept = "";
    rest.forEach(c => { if(/^(head|hod|lead|subject lead|head of department)/i.test(c)) role = "hod"; else if(/^(teacher|lecturer|staff|tutor)$/i.test(c)) role = "teacher"; else { const d = depts.find(x => (x.name || "").toLowerCase() === c.toLowerCase()); if(d) dept = d.id; else name = name ? name + " " + c : c; } });
    if(!name) name = email.split("@")[0].replace(/[._-]+/g, " ").replace(/\b\w/g, c => c.toUpperCase()); if(seen.has(email)){ rows.push({bad: "In the list twice", raw: email}); return; } seen.add(email);
    rows.push({email, name: name.slice(0, 80), role, dept}); }); return rows; }
function bulkSection(sec){ if(window.claude || typeof me === "undefined" || !me || me.demo || !(me.canTeam || ["owner", "hod", "superadmin"].includes(me.role))) return ""; const b = bulk;
  if(!b) return sec("stBulk", "Add several people at once", "Paste a list, or upload a spreadsheet saved as CSV. Each person gets an email inviting them in.", `<button type="button" class="btn btn-sm btn-outline-primary" data-bk="open">Add a list of people</button>`);
  const rows = b.rows || [], good = rows.filter(r => !r.bad), depts = (typeof team !== "undefined" && team && team.depts) || [], dn = id => (depts.find(d => d.id === id) || {}).name || "";
  return sec("stBulk", "Add several people at once", "One person on each line: name, email, and if you like their role (teacher or head of department) and department. Copying the columns straight out of a spreadsheet works too.", `
    <textarea class="form-control form-control-sm" id="bkText" rows="6" placeholder="Tia Teach, tia@hilltop.ac.uk&#10;Hal Head, hal@hilltop.ac.uk, head of department" ${b.busy ? "disabled" : ""}>${esc(b.text)}</textarea>
    <div class="d-flex flex-wrap gap-2 align-items-center mt-2"><label class="btn btn-sm btn-outline-secondary mb-0" for="bkFile">Upload a CSV file</label><input type="file" id="bkFile" accept=".csv,.txt,text/csv,text/plain" class="visually-hidden"><button type="button" class="btn btn-sm btn-outline-primary" data-bk="check" ${b.busy ? "disabled" : ""}>Check the list</button>${good.length && !b.done ? `<button type="button" class="btn btn-sm btn-primary" data-bk="go" ${b.busy ? "disabled" : ""}>${b.busy ? `Adding ${b.at} of ${good.length}...` : `Add ${good.length} ${good.length === 1 ? "person" : "people"}`}</button>` : ""}<button type="button" class="btn btn-sm btn-link" data-bk="close">Close</button></div>
    ${rows.length ? `<div class="table-responsive mt-2"><table class="table table-sm align-middle mb-0 bk-t"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Department</th><th></th></tr></thead><tbody>${rows.map(r => r.bad ? `<tr class="bk-bad"><td colspan="4">${esc(r.raw)}</td><td>${esc(r.bad)}</td></tr>` : `<tr><td>${esc(r.name)}</td><td>${esc(r.email)}</td><td>${r.role === "hod" ? "Head of department" : "Teacher"}</td><td>${esc(dn(r.dept) || "This department")}</td><td class="${r.res && r.res !== "Added" ? "text-danger" : "text-success"}">${esc(r.res || "")}</td></tr>`).join("")}</tbody></table></div>` : ""}
    ${b.done ? `<p class="small mb-0 mt-2" role="status"><b>${rows.filter(r => r.res === "Added").length} added.</b> ${rows.some(r => r.res && r.res !== "Added") ? "The ones in red weren't added. The reason is next to each." : "Everyone has been emailed."}</p>` : ""}`); }
const _accountSections88 = accountSections;
