if(typeof render === "function"){ const _render89 = render; render = function(){ const r = _render89.apply(this, arguments); try{ nxRow(); }catch(e){ console.error(e); } return r; }; }   // the lesson is redrawn after it is shown (pictures arriving, a save), so the row is put back each time
