  const steps = [["Visited the site", f.visitors, "Public pages, once a day per visitor, robots left out"], ["Started an account", f.signups, "On their own, in the last 30 days"], ["Built a lesson", f.built, "Of those accounts"], ["Paying", f.paid, "Of those accounts"]];
