/* ----- your college or school, found as you type. Answers are remembered, and a longer word is narrowed from the last answer without asking the server again ----- */
const instMem = new Map(); let instSeq = 0;
async function instFind(q){ q = q.trim().toLowerCase().replace(/\s+/g, " "); if(q.length < 2) return [];
  if(instMem.has(q)) return instMem.get(q);
  for(let n = q.length - 1; n >= 2; n--){ const p = instMem.get(q.slice(0, n)); if(p && p.length < 8){ const w = q.split(" "), r = p.filter(x => w.every(k => (x.name + " " + x.town + " " + x.postcode + " " + x.postcode.replace(/ /g, "") + " " + x.ref + " " + x.type).toLowerCase().includes(k))); instMem.set(q, r); return r; } }   // fewer than a full page came back for the shorter word, so everything that could match is already here
  const r = await fetch("inst.php?v=" + ((authCfg && authCfg.dirv) || 0) + "&q=" + encodeURIComponent(q), {credentials: "omit"}); if(!r.ok) throw new Error("inst " + r.status);
  const t = await r.text(); let j; try{ j = JSON.parse(t.slice(Math.max(0, t.indexOf("{")))); }catch{ throw new Error("inst answer"); } const out = j.results || []; if(out.length) instMem.set(q, out); return out; }
function instAuto(input, list, onPick){ let hits = [], at = -1, t = 0; const FREE = lead => `<li class="ep-none ep-free" role="none">${lead}<button type="button" tabindex="-1" data-free="1">It's not in the list</button></li>`;
  const hl = (s, q) => { const i = s.toLowerCase().indexOf(q.toLowerCase()); return i < 0 ? esc(s) : esc(s.slice(0, i)) + "<mark>" + esc(s.slice(i, i + q.length)) + "</mark>" + esc(s.slice(i + q.length)); };
  const draw = () => { const q = input.value.trim().split(/\s+/)[0] || ""; list.innerHTML = hits.map((h, i) => `<li role="option" id="${list.id}-${i}" aria-selected="${i === at}"><button type="button" tabindex="-1" data-i="${i}" class="${i === at ? "on" : ""}"><span class="fw-semibold">${hl(h.name, q)}</span>${h.cols && h.cols.length ? ` <span class="badge text-bg-success fw-normal">Uses Crafticulum</span>` : ""}<small>${esc([h.town, h.postcode].filter(Boolean).join(" "))}${h.type ? " · " + esc(h.type) : ""}</small></button></li>`).join(""); if(hits.length && authCfg && authCfg.dir) list.innerHTML += FREE("None of these? "); input.setAttribute("aria-expanded", String(hits.length > 0)); if(at >= 0) input.setAttribute("aria-activedescendant", list.id + "-" + at); else input.removeAttribute("aria-activedescendant"); };
  const close = () => { hits = []; at = -1; draw(); }, pick = i => { const h = hits[i]; if(!h) return; input.value = h.name; close(); onPick(h); };
  input.addEventListener("input", () => { onPick(null); clearTimeout(t); const q = input.value, mine = ++instSeq; if(q.trim().length < 2) return close(); const go = async () => { try{ const r = await instFind(q); if(mine !== instSeq) return; hits = r; at = -1; draw(); if(!r.length) list.innerHTML = `<li class="ep-none" role="status">${authCfg && authCfg.dir ? "No match in the list. Check the spelling, or try the town or postcode." : ""}</li>` + (authCfg && authCfg.dir ? FREE("") : ""); }catch{ if(mine === instSeq) list.innerHTML = `<li class="ep-none" role="alert">The list couldn't be searched just now. You can still type the name.</li>`; } }; if(instMem.has(q.trim().toLowerCase().replace(/\s+/g, " "))) go(); else t = setTimeout(go, 110); });
  input.addEventListener("keydown", e => { if(!hits.length) return; if(e.key === "ArrowDown" || e.key === "ArrowUp"){ e.preventDefault(); at = (at + (e.key === "ArrowDown" ? 1 : -1) + hits.length + (at < 0 && e.key === "ArrowUp" ? 1 : 0)) % hits.length; draw(); } else if(e.key === "Enter" && at >= 0){ e.preventDefault(); pick(at); } else if(e.key === "Escape"){ e.stopPropagation(); close(); } });
  list.addEventListener("mousedown", e => { const b = e.target.closest("button"); if(!b) return; e.preventDefault(); if(b.dataset.free){ close(); list.innerHTML = ""; return onPick(null, true); } pick(+b.dataset.i); });
  input.addEventListener("blur", () => setTimeout(close, 150)); }
