/* the sign-in shown in a pop-up on the public pages: this same page, in a frame, with only the form. It tells the page outside how tall it is, when the person is in, and when they press Escape */
const AUTH_EMBED = /[?&]embed=1\b/.test(location.search) && window.parent !== window;
if(AUTH_EMBED){ (() => {
  const say = (type, more) => { try{ window.parent.postMessage(Object.assign({cc: "auth", type}, more || {}), location.origin); }catch{} };
  document.documentElement.classList.add("auth-embed"); const base = document.createElement("base"); base.target = "_top"; document.head.appendChild(base);   // anything that leaves this page (Microsoft, the college sign-in, Terms) takes the whole window with it
  let done = false, last = 0;
  const tick = () => { if(done) return; if(typeof me !== "undefined" && me && me.email && !authGate){ done = true; return say("done"); }
    const side = document.querySelector("#authLanding .al-side"); if(side && !$("#authLanding").hidden){ const h = Math.ceil(side.scrollHeight); const cs = getComputedStyle(side), key = h + cs.backgroundColor; if(h && key !== last){ last = key; say("size", {h, bg: cs.backgroundColor, fg: cs.color}); } } };   // the colours go too, so the frame around the form matches it in light and dark
  setInterval(tick, 200); addEventListener("load", tick);
  document.addEventListener("keydown", e => { if(e.key === "Escape" && !e.defaultPrevented && !document.querySelector(".ep-hits li")) say("close"); });
})(); }

function parseJsonReply(text){
  let t = String(text || "").trim().replace(/^```(?:json)?\s*/i, "").replace(/```\s*$/, "");
  try{ return JSON.parse(t); }catch{}
  const a = t.indexOf("{"), b = t.lastIndexOf("}");
  if(a >= 0 && b > a){ try{ return JSON.parse(t.slice(a, b + 1)); }catch{} }
  throw {code: "invalid_json"};
}
async function askServer(prompt, tries, meta){
  const r = await fetch("ai.php?a=ask", {method:"POST", headers:{"Content-Type":"application/json"}, credentials:"same-origin", body: JSON.stringify(meta && meta.tool ? {prompt, tool: meta.tool, mins: meta.mins || 0} : {prompt}), signal: meta && meta.signal || undefined}).catch(e => { if(e && e.name === "AbortError") throw e; return null; });
  if(!r) throw {code: "network", message: "No connection to the server."};
  if(r.status === 401 && (tries || 0) < 2){ const ok = await askLogin(); if(!ok) throw {code: "cancelled"}; return askServer(prompt, (tries || 0) + 1, meta); }
  let j = {}; try{ j = await r.json(); }catch{}
  if(r.status === 429) throw {code: "rate_limited"};
  if(r.status === 403) throw {code: "noperm"};
  if(!r.ok){   // say what actually went wrong, so it can be fixed
    const why = j.error || (r.status === 504 || r.status === 524 || r.status === 408 ? "The server stopped waiting before Crafticulum AI finished. Try again, or try a shorter lesson." : `The server answered with error ${r.status} and no details. Ask your web host to check the PHP error log.`);
    try{ ERR.server = why; }catch{}
    throw {code: "server", message: why};
  }
  return j.text || "";
}
const serverSample = Object.assign(async (prompt, o) => ({text: await askServer(String(prompt), 0, o && o.meta), truncated: false}), {
  json: async (prompt, o) => parseJsonReply(await askServer(typeof prompt === "string" ? prompt : JSON.stringify(prompt), 0, o && o.meta))
});
async function storeCall(a, body){
  const r = await fetch("store.php?a=" + a, {method:"POST", headers:{"Content-Type":"application/json"}, credentials:"same-origin", body: JSON.stringify(body || {})});
  if(r.status === 401) throw {code: "auth"};
  if(!r.ok) throw {code: "server"};
  return r.json();
}
async function serverDb(){
  if(typeof meLoad === "function" && !(await meLoad())) return null;
  let all;
  try{ all = await storeCall("all"); }
  catch(e){ if(!e || e.code !== "auth") return null; if(!(await askLogin())) return null; try{ all = await storeCall("all"); }catch{ return null; } }
  const store = (typeof ccOutboxApply === "function" ? ccOutboxApply((all && all.docs) || {}) : ((all && all.docs) || {})), subs = [];
  const snap = p => ({docs: Object.keys(store).filter(k => k.startsWith(p + "/") && !k.slice(p.length + 1).includes("/")).map(k => ({id: k.slice(p.length + 1), data: () => store[k]})).sort((a, b) => ((b.data() || {}).updatedAt || 0) - ((a.data() || {}).updatedAt || 0))});
  const fire = p => subs.forEach(([q, cb]) => { if(p.startsWith(q + "/")) setTimeout(() => cb(snap(q)), 0); });
  const send = (a, body) => typeof ccOutboxSend === "function" ? ccOutboxSend(a, body) : storeCall(a, body).catch(async e => { if(e && e.code === "auth" && await askLogin()) return storeCall(a, body); throw e; });
  const docRef = p => ({
    set: async v => { store[p] = JSON.parse(JSON.stringify(v)); fire(p); await send("set", {path: p, data: store[p]}); },
    get: async () => ({exists: p in store, data: () => store[p]}),
    delete: async () => { delete store[p]; fire(p); await send("del", {path: p}); }
  });
  const col = p => { const c = {doc: id => docRef(p + "/" + id), orderBy: () => c, limit: () => c, onSnapshot: cb => { subs.push([p, cb]); setTimeout(() => cb(snap(p)), 0); return () => {}; }}; return c; };
  return {collection: col, doc: docRef};
}
const browserDownloads = {save: async ({filename, data}) => {
  const url = URL.createObjectURL(data instanceof Blob ? data : new Blob([data]));
  const a = document.createElement("a"); a.href = url; a.download = filename || "download"; document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 4000);
}};
